import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext
    // 【新增】标记是否在页面出现时自动开始播放
    let autoPlayOnAppear: Bool
    @EnvironmentObject var authManager: AuthManager

    // 【修改】将 @State 替换为 @AppStorage，使用固定的 Key "isGlobalEnglishMode"
    // 这样列表页和详情页共享同一个持久化状态
    @AppStorage("isGlobalEnglishMode") private var isEnglishMode = false

    @ObservedObject var viewModel: NewsViewModel
    @ObservedObject var resourceManager: ResourceManager

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var unreadCountForGroup: Int = 0
    @State private var totalUnreadCountForContext: Int = 0

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    @State private var didCommitOnDisappear = false

    // 【修改】更新图片下载状态变量以支持详细进度
    @State private var isDownloadingImages = false
    @State private var downloadProgress: Double = 0.0
    @State private var downloadProgressText = ""

    @State private var showErrorAlert = false
    @State private var errorMessage = ""

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel, resourceManager: ResourceManager, autoPlayOnAppear: Bool = false) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel
        self.resourceManager = resourceManager
        self.autoPlayOnAppear = autoPlayOnAppear
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCountForGroup: unreadCountForGroup,
                totalUnreadCount: totalUnreadCountForContext,
                isEnglishMode: $isEnglishMode, 
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                requestNextArticle: {
                    await self.switchToNextArticleAndStopAudio()
                },
                // 【修改】传递 onAudioToggle 闭包
                onAudioToggle: {
                    handleAudioToggle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                // 【修改】使用词典：无更多文章
                ToastView(message: Localized.noMore) 
            }

            // 常驻的悬浮按钮
            MiniAudioBubbleView(
                isPlaybackActive: audioPlayerManager.isPlaybackActive,
                onTap: { handleBubbleTap() }
            )
            .padding(.bottom, 10)
            .transition(.move(edge: .leading).combined(with: .opacity))
            .zIndex(2) // 确保在详情页之上

            // 条件显示的完整播放器
            if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
                AudioPlayerView(
                    playerManager: audioPlayerManager,
                    playNextAndStart: {
                        Task {
                            await switchToNextArticle(shouldAutoplayNext: true)
                        }
                    },
                    toggleCollapse: {
                        withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                            isMiniPlayerCollapsed = true
                        }
                    }
                )
                .padding(.horizontal)
                // 【修改】增大底部间距，将播放器整体上移，避免重叠
                .padding(.bottom, 30)
                .transition(.move(edge: .bottom).combined(with: .opacity))
                .zIndex(3) // 确保在悬浮按钮之上
            }

            // 更新图片下载遮罩层UI以显示详细进度
            if isDownloadingImages {
                VStack(spacing: 12) {
                    Text(Localized.imageLoading) // 使用词典：正在加载图片
                        .font(.headline)
                        .foregroundColor(.white)

                    ProgressView(value: downloadProgress)
                        .progressViewStyle(LinearProgressViewStyle(tint: .white))
                        .padding(.horizontal, 40)

                    Text(downloadProgressText)
                        .font(.caption)
                        .foregroundColor(.white.opacity(0.8))
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.75))
                .edgesIgnoringSafeArea(.all)
                .zIndex(4) // 最高层级
            }
        }
        .onAppear {
            didCommitOnDisappear = false
            updateUnreadCounts()

            Task {
                await preDownloadNextArticleImages()
            }

            audioPlayerManager.onNextRequested = {
                Task {
                    await self.switchToNextArticle(shouldAutoplayNext: true)
                }
            }
            audioPlayerManager.onPlaybackFinished = { }

            // 【新增】处理进入页面后的自动播放逻辑
            if autoPlayOnAppear {
                // 稍微延迟一点，确保视图加载完成，且避免和系统的转场动画冲突
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    if !audioPlayerManager.isPlaybackActive {
                        startPlayback()
                    }
                }
            }
        }
        .onDisappear {
            guard !didCommitOnDisappear else { return }
            didCommitOnDisappear = true

            audioPlayerManager.stop()
            _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)
            viewModel.commitPendingReads()
        }
        .onChange(of: currentArticle) { _, newArticle in
            updateUnreadCounts()
            Task {
                await preDownloadNextArticleImages()
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
        .alert("", isPresented: $showErrorAlert, actions: {
            Button(Localized.ok, role: .cancel) { } // 使用词典：好的
        }, message: {
            Text(errorMessage)
        })
    }

    // 【修改】更新处理悬浮按钮点击的逻辑
    private func handleBubbleTap() {
        // 【新增逻辑】如果完整播放器是展开状态，并且音频正在播放，则点击悬浮按钮执行最小化操作
        if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = true
            }
        }
        // 如果音频正在播放（但播放器是收起的），点击悬浮按钮则展开完整播放器
        else if audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = false
            }
        } else {
            // 如果未播放，点击则开始播放
            startPlayback()
        }
    }

    // 处理右上角工具栏按钮点击的逻辑
    private func handleAudioToggle() {
        if audioPlayerManager.isPlaybackActive {
            audioPlayerManager.stop()
        } else {
            startPlayback()
        }
    }

    // 一个统一的开始播放的辅助函数
    private func startPlayback() {
        // 开始播放时，确保完整播放器是展开状态
        isMiniPlayerCollapsed = false

        let rawText: String
        let title: String
        let language: String

        // 根据 isEnglishMode 决定播放内容
        if isEnglishMode,
           let engText = currentArticle.article_eng, !engText.isEmpty,
           let engTitle = currentArticle.topic_eng {
            rawText = engText
            title = engTitle
            language = "en-US"
        } else {
            rawText = currentArticle.article
            title = currentArticle.topic
            language = "zh-CN"
        }

        let paragraphs = rawText
            .components(separatedBy: .newlines)
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        let fullText = paragraphs.joined(separator: "\n\n")

        // 传入 language 参数
        audioPlayerManager.startPlayback(text: fullText, title: title, language: language)
    }

    private func updateUnreadCounts() {
        let sourceNameToUse: String?
        switch navigationContext {
        case .fromSource(let name):
            sourceNameToUse = name
        case .fromAllArticles:
            sourceNameToUse = nil
        }
        self.unreadCountForGroup = viewModel.getUnreadCountForDateGroup(
            timestamp: currentArticle.timestamp,
            inSource: sourceNameToUse
        )
        self.totalUnreadCountForContext = viewModel.getEffectiveUnreadCount(
            inSource: sourceNameToUse
        )
    }

    private func switchToNextArticleAndStopAudio() async {
        audioPlayerManager.stop()
        await switchToNextArticle(shouldAutoplayNext: false)
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) async {

        // 【新增】在这里调用 ReviewManager
        // 逻辑：用户决定看下一篇，说明刚刚这就这篇看完了/听完了，记录一次有效交互
        ReviewManager.shared.recordInteraction()

        if shouldAutoplayNext {
            audioPlayerManager.prepareForNextTransition()
        }

        _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        // 【优化】寻找下一篇文章的操作虽然很快，但在极大数据量下可能微卡
        // 由于 viewModel 是 MainActor，我们直接调用即可。
        // 关键在于：获取到 next 之后，不要立即做太重的同步操作
        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            await MainActor.run {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
                audioPlayerManager.stop()
            }
            return
        }

        // ... (图片下载逻辑保持不变) ...
        // 这里的图片下载已经是异步的，不会卡顿
        if !next.article.images.isEmpty {
             // ... 图片下载代码 ...
             let imagesAlreadyExist = resourceManager.checkIfImagesExistForArticle(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )

            if !imagesAlreadyExist {
                // 1. 设置下载状态的初始值
                await MainActor.run {
                    isDownloadingImages = true
                    downloadProgress = 0.0
                    downloadProgressText = Localized.imagePrepare // 使用词典：准备中
                }

                do {
                    // 2. 调用下载方法，并传入一个闭包来处理进度更新
                    try await resourceManager.downloadImagesForArticle(
                        timestamp: next.article.timestamp,
                        imageNames: next.article.images,
                        progressHandler: { current, total in
                            // 这个闭包会在 MainActor 上被调用，可以直接更新UI状态
                            self.downloadProgress = total > 0 ? Double(current) / Double(total) : 0
                            // 【修改】使用词典拼接：已下载 X / Y
                            self.downloadProgressText = "\(Localized.imageDownloaded) \(current) / \(total)"
                        }
                    )
                } catch {
                    await MainActor.run {
                        isDownloadingImages = false
                        // 移除这里的报错弹窗和音频停止逻辑
                    }
                    print("下一篇图片预下载失败，跳过等待继续切换: \(error.localizedDescription)")
                    // 移除原来的 return，让程序继续往下执行切换文章的逻辑！
                }


                // 3. 下载成功后，隐藏遮罩
                await MainActor.run {
                    isDownloadingImages = false
                }
            }
        }

        // --- 【核心修改开始】 ---

        // 移除原有的 "shouldKeepEnglish" 强制切换逻辑
        // 我们希望保留用户的“偏好设置”，即使当前文章没有英文，开关依然是开着的(只是显示中文)
        // 这样下一篇如果有英文，依然会自动显示英文。

        await MainActor.run {
            // 使用 easeInOut 动画，配合 LazyVStack，切换应该是丝滑的
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        }

        if shouldAutoplayNext {
            await MainActor.run {
                // 自动播放时，确保播放器是展开的
                self.isMiniPlayerCollapsed = false

                // 3. 根据全局 isEnglishMode 和当前文章是否有英文，决定播放语言
                let rawText: String
                let title: String
                let language: String

                // 动态判断当前这篇新文章能不能播英文
                let canPlayEnglish = self.isEnglishMode && 
                                     (next.article.article_eng != nil && !next.article.article_eng!.isEmpty)

                if canPlayEnglish,
                   let engText = next.article.article_eng, 
                   let engTitle = next.article.topic_eng {
                    // 播放英文
                    rawText = engText
                    title = engTitle
                    language = "en-US"
                } else {
                    // 播放中文
                    rawText = next.article.article
                    title = next.article.topic
                    language = "zh-CN"
                }

                let paragraphs = rawText
                    .components(separatedBy: .newlines)
                    .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                let fullText = paragraphs.joined(separator: "\n\n")

                // 【修复】明确传入 "zh-CN"，确保逻辑一致
                self.audioPlayerManager.startPlayback(text: fullText, title: title, language: language)
            }
        }
    }

    private func preDownloadNextArticleImages() async {
        print("开始检查并预下载下一篇文章的图片...")

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            print("没有找到下一篇未读文章，无需预下载。")
            return
        }

        guard !next.article.images.isEmpty else {
            print("下一篇文章 '\(next.article.topic)' 没有图片，无需预下载。")
            return
        }

        do {
            try await resourceManager.preDownloadImagesForArticleSilently(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )
        } catch {
            print("静默预下载下一篇文章的图片失败: \(error.localizedDescription)")
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }

    struct ToastView: View {
        let message: String
        var body: some View {
            Text(message)
                .font(.subheadline)
                .padding()
                .background(Color.black.opacity(0.75))
                .foregroundColor(.white)
                .cornerRadius(10)
                .padding(.bottom, 50)
                .transition(.opacity.animation(.easeInOut))
        }
    }
}

import SwiftUI
import UIKit
import Photos

// MARK: - ActivityView (保持不变)
struct ActivityView: UIViewControllerRepresentable {
    let activityItems: [Any]
    let applicationActivities: [UIActivity]? = nil
    func makeUIViewController(context: Context) -> UIActivityViewController {
        let vc = UIActivityViewController(activityItems: activityItems, applicationActivities: applicationActivities)
        vc.modalPresentationStyle = .automatic
        return vc
    }
    func updateUIViewController(_ uiViewController: UIActivityViewController, context: Context) {}
}

// MARK: - ImageLoader (保持不变)
@MainActor
final class ImageLoader: ObservableObject {
    @Published var image: UIImage?
    @Published var isLoading = false
    @Published var isFailed = false // 新增失败状态标记

    private static var cache = NSCache<NSString, UIImage>()

    // 改为异步方法，并返回一个 Bool 表示本地加载是否成功
    func load(from path: String) async -> Bool {
        let cacheKey = path as NSString

        // 1. 先检查内存缓存
        if let cached = Self.cache.object(forKey: cacheKey) {
            self.image = cached
            self.isFailed = false
            return true
        }

        // 2. 异步加载本地文件
        isLoading = true
        self.isFailed = false

        let loadedImage = await Task.detached(priority: .userInitiated) {
            UIImage(contentsOfFile: path)
        }.value

        self.isLoading = false

        if let img = loadedImage {
            Self.cache.setObject(img, forKey: cacheKey)
            self.image = img
            return true
        } else {
            self.isFailed = true
            return false // 图片不存在或已损坏
        }
    }

    static func clearCache() {
        cache.removeAllObjects()
    }
}

// MARK: - ArticleDetailView
struct ArticleDetailView: View {
    let article: Article
    let sourceName: String
    let unreadCountForGroup: Int
    let totalUnreadCount: Int
    // 【修改】改为 Binding，接收父视图的状态
    @Binding var isEnglishMode: Bool 
    @ObservedObject var viewModel: NewsViewModel

    // 【修改】保持对 manager 的观察以获取状态
    @ObservedObject var audioPlayerManager: AudioPlayerManager
    var requestNextArticle: () async -> Void
    // 【新增】用于处理右上角音频按钮点击的闭包
    var onAudioToggle: () -> Void

    @State private var isSharePresented = false
    @State private var showCopyToast = false
    @State private var toastMessage = ""

    // 【新增】控制推广弹窗显示
    @State private var showNewsPromoSheet = false

    // 【优化】使用 @State 缓存耗时计算的结果，避免 body 每次刷新都重算
    @State private var cachedParagraphs: [String] = []
    @State private var cachedRemainingImages: [String] = []
    @State private var cachedInsertionInterval: Int = 1
    @State private var cachedDistributeEvenly: Bool = false
    // 【新增】标记内容是否准备就绪，防止闪烁
    @State private var isContentReady = false

    // 【修改】控制自定义分享菜单
    @State private var showCustomShareSheet = false
    // 【新增】控制系统分享（点击“更多”后显示）
    @State private var showSystemActivitySheet = false
    // 【新增】控制微信引导页
    @State private var showWeChatGuideSheet = false

    // 【新增 2】判断是否存在有效的英文版本
    private var hasEnglishVersion: Bool {
        guard let tEng = article.topic_eng, !tEng.isEmpty,
              let aEng = article.article_eng, !aEng.isEmpty else {
            return false
        }
        return true
    }

    // 获取当前应显示的标题
    private var displayTopic: String {
        (isEnglishMode && hasEnglishVersion) ? (article.topic_eng ?? article.topic) : article.topic
    }

    // 【新增】获取当前应显示的来源名称 (Banner 标题)
    private var displaySourceName: String {
        // 如果是英文模式，尝试在 viewModel 的 sources 列表中查找对应的英文名
        if isEnglishMode {
            // 注意：这里的 sourceName 通常是中文名（作为ID使用），我们用它来查找 Source 对象
            if let source = viewModel.sources.first(where: { $0.name == sourceName }) {
                return source.name_en
            }
        }
        // 默认为传入的 sourceName (中文)
        return sourceName
    }

    // 【修改】去掉星期几，只保留日期
    private var monthDayFormatter: DateFormatter {
        let f = DateFormatter()
        // 原代码：f.dateFormat = Localized.dateFormatShort

        // 修改为：使用模板指定只显示 月(M) 和 日(d)
        // 这样系统会自动根据 Locale 去掉星期几。
        // 中文环境下显示 "1月17日"，英文环境下显示 "Jan 17"
        f.setLocalizedDateFormatFromTemplate("MMMd")

        f.locale = Localized.currentLocale
        return f
    }

    private var longDateFormatter: DateFormatter {
        let f = DateFormatter()
        f.dateFormat = Localized.dateFormatFull
        f.locale = Localized.currentLocale
        return f
    }

    private static let parsingFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "yyMMdd"
        return f
    }()

    var body: some View {
        ZStack {
            ScrollView {
                // 【优化 1】使用 LazyVStack 替代 VStack
                // 这使得只有进入屏幕的段落和图片才会被渲染，极大减少长文章的内存占用和卡顿
                LazyVStack(alignment: .leading, spacing: 16) {

                    // 头部信息区域
                    VStack(alignment: .leading, spacing: 8) {
                        // --- 修改开始 ---
                        HStack(alignment: .center, spacing: 10) {
                            Text(formatDate(from: article.timestamp))
                                .font(.caption).foregroundColor(.gray)

                                // 如果存在 url 且格式正确，则显示超链接
                            if let urlString = article.url, let url = URL(string: urlString) {
                                Link(destination: url) {
                                    HStack(spacing: 2) {
                                        Text(Localized.originalLink)
                                        Image(systemName: "arrow.up.right")
                                    }
                                    .font(.caption)
                                    .foregroundColor(.blue) // 经典的链接蓝色
                                }
                            }
                        }

                        // 【修改 1】这里使用动态的 displayTopic
                        Text(displayTopic)
                            .font(.system(.title, design: .serif)).fontWeight(.bold)
                            // 英文标题通常不需要那么紧凑，可以微调，这里保持一致即可
                            .animation(.none, value: isEnglishMode) 
                    }
                    .padding(.horizontal, 20)
                    // 【优化】给头部一个固定的 ID，防止 LazyVStack 刷新时跳动
                    .id("Header-\(article.id)")

                    if let firstImage = article.images.first {
                        ArticleImageView(imageName: firstImage, timestamp: article.timestamp)
                            .padding(.horizontal, 0) // 图片内部已有 padding
                    }

                    // 【优化】仅当内容准备好后才显示段落，避免布局跳变
                    if isContentReady {
                        ForEach(cachedParagraphs.indices, id: \.self) { pIndex in
                            Text(cachedParagraphs[pIndex])
                                .font(.custom("NewYork-Regular", size: 21))
                                .lineSpacing(15)
                                .padding(.horizontal, 18)
                                // 【优化】给每个段落添加 id，帮助 LazyVStack 识别
                                .id("p-\(article.id)-\(pIndex)")
                                .gesture(
                                    LongPressGesture()
                                        .onEnded { _ in
                                            UIPasteboard.general.string = cachedParagraphs[pIndex]
                                            self.toastMessage = Localized.paragraphCopied
                                            withAnimation(.spring()) { self.showCopyToast = true }
                                            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                                                withAnimation(.spring()) {
                                                    self.showCopyToast = false
                                                }
                                            }
                                        }
                                )

                            // 图片插入逻辑
                            if (pIndex + 1) % cachedInsertionInterval == 0 {
                                let imageIndexToInsert = (pIndex + 1) / cachedInsertionInterval - 1
                                if imageIndexToInsert < cachedRemainingImages.count {
                                    ArticleImageView(
                                        imageName: cachedRemainingImages[imageIndexToInsert],
                                        timestamp: article.timestamp
                                    )
                                    .id("img-\(article.id)-\(imageIndexToInsert)")
                                }
                            }
                        }

                        if !cachedDistributeEvenly && cachedRemainingImages.count > cachedParagraphs.count {
                            let extraImages = cachedRemainingImages.dropFirst(cachedParagraphs.count)
                            ForEach(Array(extraImages), id: \.self) { imageName in
                                ArticleImageView(imageName: imageName, timestamp: article.timestamp)
                            }
                        }
                    } else {
                        // 占位符，防止进入页面时一片空白
