import Foundation
import Combine
import SwiftUI

// 桥接壳：对外 API 基本不变，但全部转发给 DataService.shared
final class DataService1 {
    static let shared = DataService1()
    private init() {}

    // 与原 API 保持相同命名
    var descriptionData1: DescriptionData1? {
        DataService.shared.descriptionData1
    }

    var tagsWeightConfig: [Double: [String]] {
        DataService.shared.tagsWeightConfig
    }

    var compareData1: [String: String] {
        // 使用合并后 DataService 中的大写映射
        DataService.shared.compareDataUppercased
    }

    var sectorsData: [String: [String]] {
        DataService.shared.sectorsData
    }

    func loadAllData() {
        // 统一由 DataService 管理加载生命周期
        DataService.shared.forceReloadData()
    }

    func getCategory(for symbol: String) -> String? {
        DataService.shared.getCategory(for: symbol)
    }
}

struct OptionBigOrder: Identifiable, Codable {
    var id = UUID() // <--- 把 'let' 改为 'var'，消除 Codable 警告
    let date: String
    let symbol: String
    let type: String       // Calls / Puts
    let expiry: String
    let strike: String
    let distance: String
    // let openInterest: String // 不显示，但在解析时会遇到，跳过即可
    let dayChange: String  // 1-Day Chg
    let price: Double      // Price (成交总额/名义价值)
}

// MARK: - 新增：High/Low 数据模型
struct HighLowItem: Identifiable, Codable {
    var id = UUID()
    let symbol: String
}

struct HighLowGroup: Identifiable {
    let id: String // 使用 timeInterval 作为 id
    let timeInterval: String
    var items: [HighLowItem]
}

// 定义模型结构
struct DescriptionData: Codable {
    let global: [String: String]?
    let stocks: [SearchStock]
    let etfs: [SearchETF]
}

// MARK: - 【新增】期权数据模型
struct OptionItem: Identifiable, Hashable {
    let id = UUID()
    let symbol: String
    let type: String       // Calls / Puts
    let expiryDate: String // Expiry Date
    let strike: String     // Strike
    let distance: String   // 【新增】Distance
    let openInterest: String // Open Interest
    let change: String     // 1-Day Chg
    let price: String      // 【新增】最新价格字段
}

// 【新增】期权榜单单项模型
struct OptionRankItem: Codable, Identifiable {
    var id: String { symbol }
    let symbol: String

    let iv: String?        // Value 1 (Latest)
    let prev_iv: String?   // Value 2 (Previous)

    // 【修改点】新增价格相关字段
    let price: Double?       // Latest Price (Server: price_latest)
    let change: Double?      // Latest Change (Server: change_latest)
    let prev_price: Double?  // Prev Price (Server: price_prev)
    let prev_change: Double? // Prev Change (Server: change_prev)
}

// 【新增】期权榜单响应模型
struct OptionRankResponse: Codable {
    let rank_up: [OptionRankItem]
    let rank_down: [OptionRankItem]
}

struct SearchStock: Identifiable, Codable, SearchDescribableItem {
    let id = UUID()
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let description3: [[String: String]]?

    enum CodingKeys: String, CodingKey {
        case symbol, name, tag, description1, description2, description3
    }
}

struct SearchETF: Identifiable, Codable, SearchDescribableItem {
    let id = UUID()
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let description3: [[String: String]]?

    enum CodingKeys: String, CodingKey {
        case symbol, name, tag, description1, description2, description3
    }
}

struct MarketCapDataItem {
    let marketCap: String
    // 【修改点 1】新增：存储原始数值用于排序
    let rawMarketCap: Double 
    let peRatio: Double?
    let pb: Double?

    init(marketCap: Double, peRatio: Double?, pb: Double?) {
        // 【修改点 2】保存原始值
        self.rawMarketCap = marketCap 
        self.marketCap = Self.formatMarketCap(marketCap)
        self.peRatio = peRatio
        self.pb = pb
    }

    private static func formatMarketCap(_ cap: Double) -> String {
        String(format: "%.0fB", cap / 1_000_000_000)
    }
}

// 1. 更新 EarningRelease 模型以匹配新格式
struct EarningRelease: Identifiable {
    let id = UUID()
    let symbol: String
    let timing: String // BMO, AMC, TNS
    let date: String   // 存储 "MM-dd" 格式的日期
    let fullDate: Date // 新增：存储完整的日期对象（用于计算）
}

// 【新增】: 定义一个枚举来表示财报和股价的组合趋势
enum EarningTrend {
    case positiveAndUp    // 财报为正，股价上涨（亮红色）
    case positiveAndDown  // 财报为正，股价下跌（暗红色）
    case negativeAndUp    // 财报为负，股价上涨（亮绿色）
    case negativeAndDown  // 财报为负，股价下跌（暗绿色）
    case insufficientData // 数据不足，无法判断（白色）
}

// 保留与 b.swift 相同的结构，供 SimilarViewModel 等使用
protocol SymbolItem {
    var symbol: String { get }
    var tag: [String] { get }
}

struct DescriptionData1: Codable {
    let stocks: [Stock1]
    let etfs: [ETF1]
}

struct Stock1: Codable, SymbolItem {
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let value: String
}

struct ETF1: Codable, SymbolItem {
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let value: String
}

class DataService: ObservableObject {
    // MARK: - Singleton
    static let shared = DataService()

    // 【修改点 1】定义 UserDefaults 的 Key
    private let strategyGroupsKey = "FinanceAppStrategyGroupsConfig"
    private let groupNamesKey = "FinanceAppGroupNamesConfig" // 新增

    // 【修改 1：添加一个数组属性来存储顺序】
    @Published var orderedStrategyGroups: [String] = [] 

    // 【新增】存储市值阀值，默认 500亿 (50B)
    @Published var optionCapLimit: Double = 500_000_000_000

    // 【新增】O(1) 的 Tag 查询映射表，解决滑动卡顿
    @Published var symbolTagsMap: [String: [String]] = [:]

    // 【修改点】存储映射表
    @Published var strategyGroupNames: Set<String> = []
    @Published var groupDisplayMap: [String: String] = [:] // 新增：Key 为英文，Value 为中文

    // 【新增】存储符合条件的最新财报数值：Key=Symbol, Value=Price
    @Published var recentEarningPrices: [String: Double] = [:]

    // 【新增】存储历史分组的涨跌幅：Key 为 "SYMBOL_DATE" (如 "AAPL_2023-10-12"), Value 为涨跌幅比例
    @Published var historyPriceChanges: [String: Double] = [:]

    // 【新增】O(1) 分类反查表（替代 O(N²) 的 getCategory）
    @Published var symbolCategoryMap: [String: String] = [:]
    // 【新增】O(1) 标签权重反查表（替代线性搜索）
    @Published var tagWeightLookup: [String: Double] = [:]

    // 【新增】存储更新时间文案
    @Published var ecoDataTimestamp: String? = nil
    @Published var introSymbolTimestamp: String? = nil

    // 【新增】存储期权大单数据
    @Published var optionBigOrders: [OptionBigOrder] = []

    // 【新增】UserDefaults Keys
    private let ecoDataKey = "FinanceAppEcoDataTime"
    private let introSymbolKey = "FinanceAppIntroSymbolTime"

    // 【新增】缓存期权指标数据：Key=Symbol, Value=(IV, SumPrice)
    @Published var optionsMetricsCache: [String: (iv: String, sum: String)] = [:]

    private init() {
        // 【修改点 3】初始化时从 UserDefaults 读取配置，同时读取到 orderedStrategyGroups】
        if let savedGroups = UserDefaults.standard.array(forKey: strategyGroupsKey) as? [String] {
            self.strategyGroupNames = Set(savedGroups)
            self.orderedStrategyGroups = savedGroups // <--- 新增这行
        }
        // 【新增】读取名称映射
        if let savedNames = UserDefaults.standard.dictionary(forKey: groupNamesKey) as? [String: String] {
            self.groupDisplayMap = savedNames
        }
        // 【新增】初始化时读取时间戳缓存
        self.ecoDataTimestamp = UserDefaults.standard.string(forKey: ecoDataKey)
        self.introSymbolTimestamp = UserDefaults.standard.string(forKey: introSymbolKey)
    }

    // 【新增】内部状态，标记是否正在加载
    private var isLoading = false 

    // MARK: - Published properties
    @Published var topGainers: [Stock] = []
    @Published var topLosers: [Stock] = []
    @Published var etfGainers: [ETF] = []
    @Published var etfLosers: [ETF] = []

    @Published var descriptionData: DescriptionData?
    // 合并新增：轻量版本（与 b.swift 一致）
    @Published var descriptionData1: DescriptionData1?

    @Published var marketCapData: [String: MarketCapDataItem] = [:]
    @Published var sectorsData: [String: [String]] = [:]

    @Published var earningHistoryData: [String: [String: [String]]] = [:]

    // 原 compareData（你已有的“合并大小写键”的策略）
    @Published var compareData: [String: String] = [:]
    // 合并新增：仅大写键映射，供 b.swift/Similar 使用
    @Published var compareDataUppercased: [String: String] = [:]

    @Published var sectorsPanel: SectorsPanel?
    @Published var symbolEarningData: [String: [Date: Double]] = [:]

    @Published var earningReleases: [EarningRelease] = []

    // 公开缓存：已获取的财报趋势
    @Published var earningTrends: [String: EarningTrend] = [:]

    // 【新增】记录正在请求中的 Symbol，防止滑动时产生海量重复请求
    private var fetchingTrendsSymbols: Set<String> = []

    // 【新增】存储 ETFs 的 Top 10 和 Bottom 10
    // 注意：这里假设 IndicesSymbol 在同一个 Target 下可见。
    // 如果报错找不到 IndicesSymbol，请将 Indices.swift 中的 IndicesSymbol 结构体定义移动到一个单独的文件或 DataService.swift 顶部。
    @Published var etfTopGainers: [IndicesSymbol] = []
    @Published var etfTopLosers: [IndicesSymbol] = []

    // High/Low
    @Published var highGroups: [HighLowGroup] = []
    @Published var lowGroups: [HighLowGroup] = []

    @Published var errorMessage: String? = nil

    @Published var globalTimeMarkers: [Date: String] = [:]
    @Published var symbolTimeMarkers: [String: [Date: String]] = [:]

    // MARK: - 新增：tags 权重（合并自 DataService1）
    @Published var tagsWeightConfig: [Double: [String]] = [:]

    // 【新增】存储 10年新高 的数据
    @Published var tenYearHighSectors: [IndicesSector] = []

    // MARK: - 【新增】期权数据存储
    // Key 是 Symbol (大写), Value 是该 Symbol 下所有的期权条目
    @Published var optionsData: [String: [OptionItem]] = [:]

    private var isDataLoaded = false
    private var isInitialLoad: Bool {
        let localVersion = UserDefaults.standard.string(forKey: "FinanceAppLocalDataVersion")
        return localVersion == nil || localVersion == "0.0"
    }

    // 【新增】更新阀值的方法
    func updateOptionCapLimit(_ limit: Double) {
        DispatchQueue.main.async {
            self.optionCapLimit = limit
        }
    }

    // 【新增】获取期权榜单数据 (Async)
    // 返回元组: (上涨列表, 下跌列表)
    func fetchOptionsRankData() async -> ([OptionRankItem], [OptionRankItem])? {
        // 【安全修复】先在主线程安全获取阀值
        let limit = await MainActor.run { self.optionCapLimit }

        let urlString = "\(DatabaseManager.shared.serverBaseURL)/query/options_rank?limit=\(String(format: "%.0f", limit))"
        guard let url = URL(string: urlString) else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let result = try JSONDecoder().decode(OptionRankResponse.self, from: data)
            return (result.rank_up, result.rank_down)
        } catch {
            print("DataService: 获取期权榜单失败: \(error)")
            return nil
        }
    }

    // 【新增】在不修改服务器的情况下，客户端自行处理逻辑
    func fetchRecentEarningPriceIfNeeded(for symbol: String) {
        let upperSymbol = symbol.uppercased()

        // 性能优化：如果已经加载过，就不再重复请求
        if recentEarningPrices[upperSymbol] != nil { return }

        Task {
            // 1. 调用现有接口获取所有财报数据
            let earnings = await DatabaseManager.shared.fetchEarningData(forSymbol: symbol)

            // 2. 客户端排序：按日期从新到旧排序
            let sortedEarnings = earnings.sorted { $0.date > $1.date }

            // 3. 取出最新的一条
            guard let latest = sortedEarnings.first else { return }

            // 4. 判断日期是否在两个月内
            let calendar = Calendar.current
            let now = Date()
            if let twoMonthsAgo = calendar.date(byAdding: .month, value: -2, to: now) {
                // 如果最新财报日期 >= 两个月前的日期
                if latest.date >= twoMonthsAgo {
                    await MainActor.run {
                        self.recentEarningPrices[upperSymbol] = latest.price
                    }
                }
            }
        }
    }

    // 【新增】批量加载期权指标
    func fetchOptionsMetrics(for symbols: [String]) async {
        // 1. 过滤掉已经缓存过的，避免重复请求
        // 注意：在后台线程读取 MainActor 属性需要 await，或者我们简单点每次都请求也行，
        // 为了性能，建议简单过滤一下：
        let needFetch = await MainActor.run {
            symbols.filter { self.optionsMetricsCache[$0] == nil }
        }

        if needFetch.isEmpty { return }

        // 分批处理：一次最多查 50 个，防止 URL 过长
        let chunkedSymbols = needFetch.chunked(into: 50) 

        // 计算预期的交易日 (只需要计算一次)
        let expectedDateStr = TradingDateHelper.getLastExpectedTradingDateString()

        for chunk in chunkedSymbols {
            // 网络请求
            let results = await DatabaseManager.shared.fetchOptionsSummaries(forSymbols: chunk)

            // 处理数据
            // 1. 这里依然用 var，因为我们需要在下面的循环里修改它
            var tempCache: [String: (iv: String, sum: String)] = [:]

            for (symbol, summary) in results {
                // 校验日期
                if let serverDateStr = summary.date, serverDateStr == expectedDateStr,
                   let iv = summary.iv, let price = summary.price, let change = summary.change {

                    let sum = price + change
                    let sumStr = String(format: "%.2f", sum)
                    tempCache[symbol] = (iv, sumStr)
                }
            }

            // 【关键修改】
            // 在进入 MainActor 之前，创建一个不可变的副本 (let)
            // 这样编译器就知道这个数据在传递过程中不会被修改了
            let finalCache = tempCache

            // 回到主线程更新 UI
            await MainActor.run {
                // 这里使用 finalCache 而不是 tempCache
                self.optionsMetricsCache.merge(finalCache) { (_, new) in new }
            }
        }
    }

    // MARK: - 【修改点 5】新增：更新策略组配置的方法
    func updateStrategyConfig(groups: [String], names: [String: String]) {
        DispatchQueue.main.async {
            self.strategyGroupNames = Set(groups)
            self.orderedStrategyGroups = groups // <--- 【修改 3：更新时保存顺序】
            self.groupDisplayMap = names
        }
        UserDefaults.standard.set(groups, forKey: strategyGroupsKey)
        UserDefaults.standard.set(names, forKey: groupNamesKey)
    }

    // 【新增】更新时间戳并持久化
    func updateTimestamps(eco: String?, intro: String?) {
        DispatchQueue.main.async {
            self.ecoDataTimestamp = eco
            self.introSymbolTimestamp = intro
        }

        if let eco = eco {
            UserDefaults.standard.set(eco, forKey: ecoDataKey)
        }
        if let intro = intro {
            UserDefaults.standard.set(intro, forKey: introSymbolKey)
        }
    }

    // 兼容之前的调用名（可选）
    func updateStrategyGroups(_ groups: [String]) {
        self.updateStrategyConfig(groups: groups, names: self.groupDisplayMap)
    }

    // 【核心修改】：将 loadData 改为异步触发，不阻塞主线程
    func loadData() {
        // 【修改】同时检查 是否已加载 和 是否正在加载
        guard !isDataLoaded, !isLoading else {
            print("DataService: 数据已加载或正在加载中，跳过重复请求。")
            return
        }

        // 标记开始加载
        self.isLoading = true

        DispatchQueue.main.async { self.errorMessage = nil }

        Task.detached(priority: .userInitiated) {
            print("DataService: 开始在后台加载数据...")

            // 1. 并行或串行加载本地文件 (IO操作)
            // 注意：这里调用的是同步方法，但在 detached Task 中运行，不会卡 UI
            await self.loadDescriptionPair()
            await self.loadSectorsData()
            await self.loadCompareDataPair()
            await self.loadSectorsPanel()
            await self.loadEarningRelease()
            await self.loadHighLowData()
            await self.loadCompareStock()
            await self.loadTagsWeight()
            await self.loadCompareETFs()
            // 【新增】加载 10年新高数据
            await self.loadTenYearHighData()
            await self.loadOptionsData() // 加载期权数据
            // 【新增】加载期权大单 CSV
            await self.loadOptionBigOrders() 
            await self.loadEarningHistory()

            await MainActor.run {
                self.isDataLoaded = true
                self.isLoading = false // 【新增】加载完成，重置 loading 状态
                print("DataService: 所有本地数据加载完毕 (UI已更新)。")
            }

            // 3. 启动网络请求 (本身就是 async 的)
            await self.loadMarketCapData()
        }
    }

    // 4. 添加具体的加载方法
    private func loadOptionBigOrders() async {
        // 自动匹配 Options_History_xxxxxx.csv
        guard let url = FileManagerHelper.getLatestFileUrl(for: "Options_History") else {
            print("DataService: Options_History 文件未找到")
            return
        }

        do {
            let content = try String(contentsOf: url, encoding: .utf8)
            let lines = content.split(separator: "\n", omittingEmptySubsequences: true)

            var newOrders: [OptionBigOrder] = []

            // 遍历行，跳过表头
            for (index, line) in lines.enumerated() {
                if index == 0 { continue } // 跳过 Header

                // CSV 格式: Run_Date,Symbol,Type,Expiry Date,Strike,Distance,OI,1-Day Chg,Price
                let parts = line.split(separator: ",").map { String($0).trimmingCharacters(in: .whitespaces) }

                if parts.count >= 9 {
                    let date = parts[0]
                    let symbol = parts[1]
                    let type = parts[2]
                    let expiry = parts[3]
                    let strike = parts[4]
                    let distance = parts[5]
                    // parts[6] 是 OI，跳过
                    let change = parts[7]
                    let priceStr = parts[8]

                    let price = Double(priceStr) ?? 0.0

                    let order = OptionBigOrder(
                        date: date,
                        symbol: symbol,
                        type: type,
                        expiry: expiry,
                        strike: strike,
                        distance: distance,
                        dayChange: change,
                        price: price
                    )
                    newOrders.append(order)
                }
            }

            // 【核心修改】在这里加入三级排序逻辑
            newOrders.sort { o1, o2 in
                // 1. 第一优先级：Run_Date
                // 假设日期格式是 YYYY-MM-DD，直接字符串比较即可
                // 使用 > 表示降序 (最新的日期排在最前面)
                if o1.date != o2.date {
                    return o1.date > o2.date
                }

                // 2. 第二优先级：Symbol
                // 日期相同的情况下，按 Symbol 字母顺序排列 (A -> Z)
                if o1.symbol != o2.symbol {
                    return o1.symbol < o2.symbol
                }

                // 3. 第三优先级：Price
                // Symbol 也相同的情况下，按金额大到小排列 (大单在前)
                return o1.price > o2.price
            }

            // 【核心修复】创建不可变副本 (Freeze the variable)
            // 将 'var' 冻结为 'let'，这样就可以安全地传给 MainActor 了
            let finalOrders = newOrders

            await MainActor.run {
                // 使用 finalOrders 而不是 newOrders
                self.optionBigOrders = finalOrders
            }

        } catch {
            print("DataService: 解析 Options_History 失败: \(error)")
        }
    }

    // MARK: - 公共方法：强制重新加载
