    // ... 其他辅助方法 parseStockLine, parseETFLine, cleanSymbol 保持不变 ...
    private func cleanSymbol(_ symbol: String) -> String {
        let pattern = "^([A-Za-z-]+)"
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []),
              let match = regex.firstMatch(in: symbol, options: [], range: NSRange(location: 0, length: symbol.count)),
              let range = Range(match.range(at: 1), in: symbol) else {
            return symbol
        }
        return String(symbol[range])
    }

    private func parseStockLine(_ line: String) -> Stock? {
        let pattern = "^(.*?)\\s+(\\S+)\\s*:\\s*([+-]?[\\d\\.]+%)\\s*(.*)$"
        let regex = try? NSRegularExpression(pattern: pattern, options: [])
        guard let match = regex?.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) else { return nil }

        guard let groupNameRange = Range(match.range(at: 1), in: line),
              let symbolRange = Range(match.range(at: 2), in: line),
              let valueRange = Range(match.range(at: 3), in: line),
              let descRange = Range(match.range(at: 4), in: line) else { return nil }

        let groupName = String(line[groupNameRange])
        let rawSymbol = String(line[symbolRange])
        let cleanedSymbol = cleanSymbol(rawSymbol)
        let value = String(line[valueRange])
        let desc = String(line[descRange])

        return Stock(groupName: groupName, rawSymbol: rawSymbol, symbol: cleanedSymbol, value: value, descriptions: desc)
    }

    private func parseETFLine(_ line: String) -> ETF? {
        let parts = line.split(separator: ":")
        guard parts.count >= 2 else { return nil }

        let rawSymbol = String(parts[0].trimmingCharacters(in: .whitespaces))
        let cleanedSymbol = cleanSymbol(rawSymbol)
        let rest = parts[1].trimmingCharacters(in: .whitespaces)

        let pattern = "^([+-]?[\\d\\.]+%)\\s+\\d+\\s+[+-]?[\\d\\.]+%\\s+(.*)$"
        let regex = try? NSRegularExpression(pattern: pattern, options: [])
        guard let match = regex?.firstMatch(in: rest, options: [], range: NSRange(location: 0, length: rest.utf16.count)) else { return nil }

        guard let valueRange = Range(match.range(at: 1), in: rest),
              let descRange = Range(match.range(at: 2), in: rest) else { return nil }

        let value = String(rest[valueRange])
        let descriptions = String(rest[descRange])

        return ETF(groupName: "ETFs", rawSymbol: rawSymbol, symbol: cleanedSymbol, value: value, descriptions: descriptions)
    }
}

extension Array {
    func chunked(into size: Int) -> [[Element]] {
        return stride(from: 0, to: count, by: size).map {
            Array(self[$0 ..< Swift.min($0 + size, count)])
        }
    }
}

import Foundation
import SQLite3

// 添加 final 和 @unchecked Sendable
final class DatabaseManager: @unchecked Sendable {
    static let shared = DatabaseManager()

    // 服务器地址，请确保与 UpdateManager 中一致
    internal let serverBaseURL = "http://106.15.183.158:5001/api/Finance"

    // 本地数据库指针
    private var db: OpaquePointer?
    // 线程锁，确保多线程访问数据库安全
    private let dbLock = NSLock()

    // 【新增】SQLite 专属串行队列，防止 GCD 全局队列线程爆炸
    private let sqliteQueue = DispatchQueue(label: "com.finance.sqliteQueue", qos: .userInitiated)

    private init() {
        // 初始化时尝试连接一次
        reconnectToLatestDatabase()
    }

    deinit {
        if db != nil {
            sqlite3_close(db)
        }
    }

    // MARK: - 数据库连接管理

    /// 尝试连接本地数据库
    /// 修复说明：使用了 MainActor.assumeIsolated 配合 DispatchQueue.main.sync
    /// 解决了 "Call to main actor-isolated instance method in a synchronous nonisolated context" 报错
    func reconnectToLatestDatabase() {
        // 1. 【修复死锁】在无锁状态下安全地从主线程获取路径
        // 绝对不能在 dbLock.lock() 之后调用 DispatchQueue.main.sync
        var dbPath: String?

        // 2. 安全地从 UpdateManager 获取路径
        // 我们定义一个闭包，专门用于在主线程上下文中执行
        let getMainActorPath = {
            // assumeIsolated 告诉编译器：此处代码已确信在主线程运行，允许调用 MainActor 方法
            return MainActor.assumeIsolated { () -> String? in
                if UpdateManager.shared.isLocalDatabaseValid() {
                    return UpdateManager.shared.getLocalDatabasePath()
                }
                return nil
            }
        }

        if Thread.isMainThread {
            // 如果已经在主线程，直接调用 assumeIsolated
            dbPath = getMainActorPath()
        } else {
            // 如果在后台线程，同步调度到主线程，然后调用 assumeIsolated
            dbPath = DispatchQueue.main.sync {
                return getMainActorPath()
            }
        }

        // 2. 获取到路径后，再加锁进行数据库底层切换
        dbLock.lock()
        defer { dbLock.unlock() }

        // 关闭旧连接
        if db != nil {
            sqlite3_close(db)
            db = nil
        }

        // 3. 根据获取到的路径执行连接
        if let validPath = dbPath {
            // sqlite3_open 接受 C 字符串，路径必须有效
            if sqlite3_open(validPath, &db) == SQLITE_OK {
                print("DBManager: ✅ 已切换至【离线模式】，加载本地数据库成功。")
            } else {
                print("DBManager: ❌ 本地数据库打开失败，回退至在线模式。")
                db = nil
            }
        } else {
            print("DBManager: 🌐 本地数据不存在或已过期，使用【在线模式】。")
        }
    }

    /// 判断当前是否处于离线模式
    private var isOfflineMode: Bool {
        return db != nil
    }

    // MARK: - Models

    struct OptionsSummary: Codable {
        let call: String?
        let put: String?
        // 【新增】匹配服务器返回的 Price 和 Change
        let price: Double?
        let change: Double?
        // 【新增】IV 字段
        let iv: String?
        // 【本次新增】日期字段，用于前端校验
        let date: String?

        // 【新增】次新 IV
