    let isLatestDate: Bool   // 新增：是否是最新日期分组
    let onToggle: () -> Void

    @EnvironmentObject var dataService: DataService

    // 标记是否已触发过此分组的涨跌幅计算，避免重复请求
    @State private var isFetchInitiated = false

