        Section {
            if isExpanded {
                VStack(spacing: 0) {
                    ForEach(symbols, id: \.self) { symbol in
                        HistorySymbolRow(
                            symbol: symbol,
                            dateStr: dateStr,
                            isLatestDate: isLatestDate,
