    // 4. 添加具体的加载方法
    private func loadOptionBigOrders() async {
        // 自动匹配 Options_History_xxxxxx.csv
        guard let url = FileManagerHelper.getLatestFileUrl(for: "Options_History") else {
            print("DataService: Options_History 文件未找到")
            return
        }

        do {
            let content = try String(contentsOf: url, encoding: .utf8)
            let lines = content.split(separator: "\n", omittingEmptySubsequences: true)

            var newOrders: [OptionBigOrder] = []

            // 遍历行，跳过表头
            for (index, line) in lines.enumerated() {
                if index == 0 { continue } // 跳过 Header

                // CSV 格式: Run_Date,Symbol,Type,Expiry Date,Strike,Distance,OI,1-Day Chg,Price
                let parts = line.split(separator: ",").map { String($0).trimmingCharacters(in: .whitespaces) }

                if parts.count >= 9 {
                    let date = parts[0]
                    let symbol = parts[1]
                    let type = parts[2]
                    let expiry = parts[3]
                    let strike = parts[4]
                    let distance = parts[5]
                    // parts[6] 是 OI，跳过
                    let change = parts[7]
                    let priceStr = parts[8]

                    let price = Double(priceStr) ?? 0.0

                    let order = OptionBigOrder(
                        date: date,
                        symbol: symbol,
                        type: type,
                        expiry: expiry,
                        strike: strike,
                        distance: distance,
                        dayChange: change,
                        price: price
                    )
                    newOrders.append(order)
                }
            }

            // 【核心修改】在这里加入三级排序逻辑
            newOrders.sort { o1, o2 in
                // 1. 第一优先级：Run_Date
                // 假设日期格式是 YYYY-MM-DD，直接字符串比较即可
                // 使用 > 表示降序 (最新的日期排在最前面)
                if o1.date != o2.date {
                    return o1.date > o2.date
                }

                // 2. 第二优先级：Symbol
                // 日期相同的情况下，按 Symbol 字母顺序排列 (A -> Z)
                if o1.symbol != o2.symbol {
                    return o1.symbol < o2.symbol
                }

                // 3. 第三优先级：Price
                // Symbol 也相同的情况下，按金额大到小排列 (大单在前)
                return o1.price > o2.price
            }

            // 【核心修复】创建不可变副本 (Freeze the variable)
            // 将 'var' 冻结为 'let'，这样就可以安全地传给 MainActor 了
            let finalOrders = newOrders

            await MainActor.run {
                // 使用 finalOrders 而不是 newOrders
                self.optionBigOrders = finalOrders
            }

        } catch {
            print("DataService: 解析 Options_History 失败: \(error)")
        }
    }

    // MARK: - 公共方法：强制重新加载
    // 注意：forceReloadData 需要重置 isLoading
    func forceReloadData() {
