    // MARK: - 【新增】加载并解析 10年新高数据
    private func loadTenYearHighData() async {
        // 使用 getLatestFileUrl 自动匹配日期后缀 (例如 10Y_newhigh_stock_251212.txt)
        guard let url = FileManagerHelper.getLatestFileUrl(for: "10Y_newhigh_stock") else {
            if !isInitialLoad {
                print("DataService: 10Y_newhigh_stock 文件未在 Documents 中找到")
            }
            return
        }

        do {
            let content = try String(contentsOf: url, encoding: .utf8)
            let lines = content.split(separator: "\n")

            // 临时字典用于分组： [GroupName: [Symbols]]
            var tempGroups: [String: [IndicesSymbol]] = [:]

            for line in lines {
                let trimmedLine = line.trimmingCharacters(in: .whitespaces)
                if trimmedLine.isEmpty { continue }

                // 解析行: "Basic_Materials HBM 0.32%*++ 18.68 铜,铜矿..."
                // 按空格分割，限制分割次数，确保 tags 部分保持完整（如果有空格）
                // 至少需要: Group, Symbol, Value
                let parts = trimmedLine.split(separator: " ", maxSplits: 4, omittingEmptySubsequences: true)

                if parts.count >= 3 {
                    let groupName = String(parts[0])
                    let symbolStr = String(parts[1])
                    let valueStr = String(parts[2]) // e.g. "0.32%*++"

                    // 处理 Price 和 Tags
                    // 原格式: Group Symbol Value Price Tags...
                    // 我们把 Price 和 Tags 合并显示在 Tags 区域，或者只显示 Tags
                    var tags: [String]? = nil

                    // 尝试提取 Price 和后续描述
                    if parts.count >= 4 {
                        let price = String(parts[3])
                        var descriptionStr = ""
                        if parts.count >= 5 {
                            descriptionStr = String(parts[4])
                        }

                        // 将价格和描述组合，或者只用描述。这里为了信息完整，我们将价格放在 tags 的第一个位置
                        let combinedTagStr = "\(price), " + descriptionStr
                        tags = combinedTagStr.split(separator: ",").map { String($0).trimmingCharacters(in: .whitespaces) }
                    }

                    let symbolItem = IndicesSymbol(
                        symbol: symbolStr,
                        name: symbolStr, // 暂时用 symbol 当名字
                        value: valueStr,
                        tags: tags
                    )

                    if tempGroups[groupName] == nil {
                        tempGroups[groupName] = []
                    }
                    tempGroups[groupName]?.append(symbolItem)
                }
            }

            // 将字典转换为 [IndicesSector] 数组，并按名称排序
            let sectors = tempGroups.map { (key, value) in
                IndicesSector(name: key, symbols: value)
            }.sorted { $0.name < $1.name }

            await MainActor.run {
                self.tenYearHighSectors = sectors
            }

        } catch {
            print("DataService: 解析 10Y_newhigh_stock 文件时出错: \(error)")
        }
    }

    // 优化：彻底解决滑动卡死、重复请求和主线程频繁切换的问题
    public func fetchEarningTrends(for symbols: [String]) {
        // 先在主线程中过滤出真正需要请求的 symbol，避免产生不必要的 Task
        let neededSymbols = symbols.filter { symbol in
            let upper = symbol.uppercased()
            // 如果已经有了数据，或者正在请求中，则跳过
            return earningTrends[upper] == nil && !fetchingTrendsSymbols.contains(upper)
        }

        guard !neededSymbols.isEmpty else { return }

        // 标记这些 symbol 正在请求中
        neededSymbols.forEach { fetchingTrendsSymbols.insert($0.uppercased()) }

        // 【关键优化】提前在主线程获取一份 sectorsData 的拷贝
        // 这样就不需要在后续的 for 循环中成百上千次地 await MainActor.run 了
        let localSectorsData = self.sectorsData

        Task.detached(priority: .userInitiated) {
            // 【核心修复 1】将任务分批 (例如每 15 个一批)，防止连续几百次敲击主线程
            let chunks = neededSymbols.chunked(into: 15)

            for chunk in chunks {
                // 用于暂存这一批的计算结果
                var tempBatch: [String: EarningTrend] = [:]

                for symbol in chunk {
                    let upperSymbol = symbol.uppercased()

                    // 1. 异步获取数据
                    let sortedEarnings = await DatabaseManager.shared.fetchEarningData(forSymbol: symbol).sorted { $0.date > $1.date }
                    var calculatedTrend: EarningTrend = .insufficientData

                    if sortedEarnings.count >= 2 {
                        let latestEarning = sortedEarnings[0]
                        let previousEarning = sortedEarnings[1]
                        let tableName = self.getLocalCategory(for: symbol, in: localSectorsData)

                        if let tableName = tableName {
                            let latestClose = await DatabaseManager.shared.fetchClosingPrice(forSymbol: symbol, onDate: latestEarning.date, tableName: tableName)
                            let previousClose = await DatabaseManager.shared.fetchClosingPrice(forSymbol: symbol, onDate: previousEarning.date, tableName: tableName)

                            if let latest = latestClose, let previous = previousClose {
                                if latestEarning.price > 0 {
                                    calculatedTrend = (latest > previous) ? .positiveAndUp : .positiveAndDown
                                } else {
                                    calculatedTrend = (latest > previous) ? .negativeAndUp : .negativeAndDown
                                }
                            }
                        }
                    }
                    // 存入暂存字典
                    tempBatch[upperSymbol] = calculatedTrend
                }

                // 【关键修复】创建一个不可变副本，供 MainActor 安全捕获，消除 Swift 6 并发报错
                let finalBatch = tempBatch

                // 【修改后】批量合并字典，避免引发成百上千次的视图重绘
                await MainActor.run {
                    self.earningTrends.merge(finalBatch) { (_, new) in new }
                    for key in finalBatch.keys {
                        self.fetchingTrendsSymbols.remove(key)
                    }
                }

                // 给主线程和其它协程喘息的机会，防止滑动卡顿
                await Task.yield() 
            }
        }
    }

        // MARK: - 【新增】批量计算历史策略股票的区间涨幅
    public func fetchHistoryPriceChanges(for items: [(symbol: String, dateStr: String)]) {
        // 过滤掉已经计算过的，避免重复请求
        let needed = items.filter { historyPriceChanges["\($0.symbol.uppercased())_\($0.dateStr)"] == nil }
        guard !needed.isEmpty else { return }

        let localSectorsData = self.sectorsData

        Task.detached(priority: .userInitiated) {
            // 每批15个，防止一次性发太多请求
            let chunks = needed.chunked(into: 15)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"

            // 获取最新交易日 (基于 TradingDateHelper)
            let latestDateStr = TradingDateHelper.getLastExpectedTradingDateString()
            let latestDate = formatter.date(from: latestDateStr)

            for chunk in chunks {
                var tempBatch: [String: Double] = [:]

                for item in chunk {
                    let upperSymbol = item.symbol.uppercased()
                    let category = self.getLocalCategory(for: upperSymbol, in: localSectorsData) ?? "Stocks"

                    guard let groupDate = formatter.date(from: item.dateStr) else { continue }

                    // 1. 获取分组那天的收盘价
                    let groupClose = await DatabaseManager.shared.fetchClosingPrice(forSymbol: upperSymbol, onDate: groupDate, tableName: category)

                    // 2. 获取最新收盘价
                    // （如果 DatabaseManager 中有直接获取最新收盘价如 fetchLatestClosingPrice 的方法，请替换掉下方逻辑）
                    // 这里我们尝试用预估的最近交易日去取，如果取不到则往前推一天容错
                    var latestClose = await DatabaseManager.shared.fetchClosingPrice(forSymbol: upperSymbol, onDate: latestDate ?? Date(), tableName: category)

                    if latestClose == nil, let fallbackDate = latestDate?.addingTimeInterval(-86400) {
                        latestClose = await DatabaseManager.shared.fetchClosingPrice(forSymbol: upperSymbol, onDate: fallbackDate, tableName: category)
                    }

                    // 3. 计算公式：(最新收盘价 - 分组时间收盘价) / 分组时间收盘价
                    if let gClose = groupClose, let lClose = latestClose, gClose > 0 {
                        let change = (lClose - gClose) / gClose
                        tempBatch["\(upperSymbol)_\(item.dateStr)"] = change
                    }
                }

                let finalBatch = tempBatch

                // 切回主线程更新 UI 状态
                // 【修改后】批量合并
                await MainActor.run {
                    self.historyPriceChanges.merge(finalBatch) { (_, new) in new }
                }

                // 协程让步，防止主线程卡顿
                await Task.yield()
            }
        }
    }

    // 【新增】本地查找 Category 的辅助方法，无需切回 MainActor
    private func getLocalCategory(for symbol: String, in data: [String: [String]]) -> String? {
        let upperSymbol = symbol.uppercased()
        for (category, symbols) in data {
            if symbols.contains(where: { $0.uppercased() == upperSymbol }) {
                return category
            }
        }
        return nil
    }


