struct StrategySymbolRow: View {
    let symbol: String
    let groupName: String
    let cleanSymbol: String

    @EnvironmentObject var dataService: DataService
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var navigateToChart = false
    @State private var showSubscriptionSheet = false

    // 静态正则，整个 App 生命周期只编译一次
    private static let _datePatternRegex = try? NSRegularExpression(pattern: #"^(\d+)([前后未])"#)

    init(symbol: String, groupName: String) {
        self.symbol = symbol
        self.groupName = groupName
        self.cleanSymbol = symbol.cleanTicker
    }

    private var earningTrend: EarningTrend {
        dataService.earningTrends[cleanSymbol.uppercased()] ?? .insufficientData
    }

    private var optionsMetrics: (iv: String, sum: String)? {
        dataService.optionsMetricsCache[cleanSymbol.uppercased()]
    }

    var body: some View {
        let sym = cleanSymbol.uppercased()
        let rawTags = dataService.symbolTagsMap[sym] ?? []
        let computedTags = rawTags.map { ($0, dataService.tagWeightLookup[$0] ?? 1.0) }
        let computedCategory = dataService.symbolCategoryMap[sym] ?? "Stocks"
        let prefixInfo = getPrefixAndColor(for: sym)

        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text(symbol)
                    .font(.system(size: 17, weight: .bold, design: .monospaced))
                    .foregroundColor(colorForEarningTrend(earningTrend))
                    .padding(.horizontal, 12)
                    .padding(.vertical, 6)
                    .background(Color.blue.opacity(0.1))
                    .cornerRadius(8)

                Spacer()

                HStack(spacing: 8) {
                    // 前缀（如"03后"）
                    if let prefix = prefixInfo.prefix {
                        Text(prefix)
                            .foregroundColor(prefixInfo.color)
                            .fontWeight(.semibold)
                    }
                    // 期权指标
                    if let metrics = optionsMetrics {
                        Text(metrics.iv)
                            .foregroundColor(colorForValueString(metrics.iv))
                            .fontWeight(.semibold)
                        Text(metrics.sum)
                            .foregroundColor(colorForValueString(metrics.sum))
                            .fontWeight(.semibold)
                    }
                    // PE（始终显示，因为只展示最新日期）
                    if let capItem = dataService.marketCapData[sym], let pe = capItem.peRatio {
                        Text("PE \(String(format: "%.1f", pe))")
                            .font(.caption)
                            .foregroundColor(.secondary)
                    }
                }
                .font(.system(size: 14))
            }

            if !computedTags.isEmpty {
                FlowLayoutTags(tags: computedTags)
            }
        }
        .padding(12)
        .contentShape(Rectangle())
        .onTapGesture {
            if usageManager.canProceed(authManager: authManager, action: .viewChart) {
                navigateToChart = true
            } else {
                showSubscriptionSheet = true
            }
        }
        .navigationDestination(isPresented: $navigateToChart) {
            ChartView(symbol: cleanSymbol, groupName: computedCategory)
        }
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
    }

    // MARK: - 前缀解析 + 颜色判断（保持原有逻辑不变）
    private func getPrefixAndColor(for sym: String) -> (prefix: String?, color: Color) {
        guard let value = dataService.compareData[sym] else { return (nil, .white) }

        let nsRange = NSRange(value.startIndex..<value.endIndex, in: value)
        var foundPrefix: String? = nil
        var suffixPart: String = ""
        var targetDate: Date? = nil

        if let match = StrategySymbolRow._datePatternRegex?.firstMatch(in: value, options: [], range: nsRange) {
            if let rFull = Range(match.range(at: 1), in: value),
               let rSuffix = Range(match.range(at: 2), in: value),
               let rFullMatch = Range(match.range(at: 0), in: value) {
                foundPrefix = String(value[rFullMatch])
                let dateStr = String(value[rFull])
                suffixPart = String(value[rSuffix])

                let formatter = DateFormatter()
                formatter.dateFormat = "MMdd"
                targetDate = formatter.date(from: dateStr)

                if let date = targetDate {
                    let components = Calendar.current.dateComponents([.month, .day], from: date)
                    let currentYear = Calendar.current.component(.year, from: Date())
                    var candidateDate = Calendar.current.date(from: DateComponents(year: currentYear, month: components.month, day: components.day))!
                    let diff = Calendar.current.dateComponents([.month], from: candidateDate, to: Date()).month ?? 0
                    if diff > 6 {
                        candidateDate = Calendar.current.date(byAdding: .year, value: -1, to: candidateDate)!
                    } else if diff < -6 {
                        candidateDate = Calendar.current.date(byAdding: .year, value: 1, to: candidateDate)!
                    }
                    targetDate = candidateDate
                }
            }
        }

        guard let target = targetDate else { return (foundPrefix, .white) }

        let today = Calendar.current.startOfDay(for: Date())
        let yesterday = Calendar.current.startOfDay(for: TradingDateHelper.getYesterday())
        let nextTradingDay = Calendar.current.startOfDay(for: TradingDateHelper.getNextTradingDay())

        var finalColor: Color = .white
        if target < yesterday {
            finalColor = .white
        } else if target == yesterday {
            finalColor = (suffixPart == "后") ? .red : .white
        } else if target == today {
            finalColor = .orange
        } else if target == nextTradingDay {
            finalColor = (suffixPart == "前") ? .red : .orange
        } else {
            finalColor = .orange
        }

        return (foundPrefix, finalColor)
    }

    private func colorForEarningTrend(_ trend: EarningTrend) -> Color {
        switch trend {
        case .positiveAndUp:    return .red
        case .negativeAndUp:    return .purple
        case .positiveAndDown:  return .cyan
        case .negativeAndDown:  return .green
        case .insufficientData: return .primary
        }
    }

    private func colorForValueString(_ valueStr: String) -> Color {
        let cleanStr = valueStr.replacingOccurrences(of: "%", with: "").trimmingCharacters(in: .whitespaces)
        if let val = Double(cleanStr) {
            if val > 0 { return .red }
            if val < 0 { return .green }
        }
        return .gray
    }
}

// MARK: - 字符串扩展：提取纯净的股票代码
extension String {
    private static let _cleanTickerRegex = try? NSRegularExpression(pattern: "^([A-Za-z0-9-]+)")

    var cleanTicker: String {
        guard let regex = String._cleanTickerRegex else { return self }
        let range = NSRange(location: 0, length: self.utf16.count)
        if let match = regex.firstMatch(in: self, options: [], range: range),
           let r = Range(match.range(at: 1), in: self) {
            return String(self[r]).replacingOccurrences(of: #"\d+$"#, with: "", options: .regularExpression)
        }
        return self
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext
    // 【新增】标记是否在页面出现时自动开始播放
    let autoPlayOnAppear: Bool
    @EnvironmentObject var authManager: AuthManager

    // 【修改】将 @State 替换为 @AppStorage，使用固定的 Key "isGlobalEnglishMode"
    // 这样列表页和详情页共享同一个持久化状态
    @AppStorage("isGlobalEnglishMode") private var isEnglishMode = false

    @ObservedObject var viewModel: NewsViewModel
    @ObservedObject var resourceManager: ResourceManager

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var unreadCountForGroup: Int = 0
    @State private var totalUnreadCountForContext: Int = 0

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    @State private var didCommitOnDisappear = false

    // 【修改】更新图片下载状态变量以支持详细进度
    @State private var isDownloadingImages = false
    @State private var downloadProgress: Double = 0.0
    @State private var downloadProgressText = ""

    @State private var showErrorAlert = false
    @State private var errorMessage = ""

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel, resourceManager: ResourceManager, autoPlayOnAppear: Bool = false) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel
        self.resourceManager = resourceManager
        self.autoPlayOnAppear = autoPlayOnAppear
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCountForGroup: unreadCountForGroup,
                totalUnreadCount: totalUnreadCountForContext,
                isEnglishMode: $isEnglishMode, 
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                requestNextArticle: {
                    await self.switchToNextArticleAndStopAudio()
                },
                // 【修改】传递 onAudioToggle 闭包
                onAudioToggle: {
                    handleAudioToggle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                // 【修改】使用词典：无更多文章
                ToastView(message: Localized.noMore) 
            }

            // 常驻的悬浮按钮
            MiniAudioBubbleView(
                isPlaybackActive: audioPlayerManager.isPlaybackActive,
                onTap: { handleBubbleTap() }
            )
            .padding(.bottom, 10)
            .transition(.move(edge: .leading).combined(with: .opacity))
            .zIndex(2) // 确保在详情页之上

            // 条件显示的完整播放器
            if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
                AudioPlayerView(
                    playerManager: audioPlayerManager,
                    playNextAndStart: {
                        Task {
                            await switchToNextArticle(shouldAutoplayNext: true)
                        }
                    },
                    toggleCollapse: {
                        withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                            isMiniPlayerCollapsed = true
                        }
                    }
                )
                .padding(.horizontal)
                // 【修改】增大底部间距，将播放器整体上移，避免重叠
                .padding(.bottom, 30)
                .transition(.move(edge: .bottom).combined(with: .opacity))
                .zIndex(3) // 确保在悬浮按钮之上
            }

            // 更新图片下载遮罩层UI以显示详细进度
            if isDownloadingImages {
                VStack(spacing: 12) {
                    Text(Localized.imageLoading) // 使用词典：正在加载图片
                        .font(.headline)
                        .foregroundColor(.white)

                    ProgressView(value: downloadProgress)
                        .progressViewStyle(LinearProgressViewStyle(tint: .white))
                        .padding(.horizontal, 40)

                    Text(downloadProgressText)
                        .font(.caption)
                        .foregroundColor(.white.opacity(0.8))
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.75))
                .edgesIgnoringSafeArea(.all)
                .zIndex(4) // 最高层级
            }
        }
        .onAppear {
            didCommitOnDisappear = false
            updateUnreadCounts()

            Task {
                await preDownloadNextArticleImages()
            }

            audioPlayerManager.onNextRequested = {
                Task {
                    await self.switchToNextArticle(shouldAutoplayNext: true)
                }
            }
            audioPlayerManager.onPlaybackFinished = { }

            // 【新增】处理进入页面后的自动播放逻辑
            if autoPlayOnAppear {
                // 稍微延迟一点，确保视图加载完成，且避免和系统的转场动画冲突
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    if !audioPlayerManager.isPlaybackActive {
                        startPlayback()
                    }
                }
            }
        }
        .onDisappear {
            guard !didCommitOnDisappear else { return }
            didCommitOnDisappear = true

            audioPlayerManager.stop()
            _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)
            viewModel.commitPendingReads()
        }
        .onChange(of: currentArticle) { _, newArticle in
            updateUnreadCounts()
            Task {
                await preDownloadNextArticleImages()
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
        .alert("", isPresented: $showErrorAlert, actions: {
            Button(Localized.ok, role: .cancel) { } // 使用词典：好的
        }, message: {
            Text(errorMessage)
        })
    }

    // 【修改】更新处理悬浮按钮点击的逻辑
    private func handleBubbleTap() {
        // 【新增逻辑】如果完整播放器是展开状态，并且音频正在播放，则点击悬浮按钮执行最小化操作
        if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = true
            }
        }
        // 如果音频正在播放（但播放器是收起的），点击悬浮按钮则展开完整播放器
        else if audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = false
            }
        } else {
            // 如果未播放，点击则开始播放
            startPlayback()
        }
    }

    // 处理右上角工具栏按钮点击的逻辑
    private func handleAudioToggle() {
        if audioPlayerManager.isPlaybackActive {
            audioPlayerManager.stop()
        } else {
            startPlayback()
        }
    }

    // 一个统一的开始播放的辅助函数
    private func startPlayback() {
        // 开始播放时，确保完整播放器是展开状态
        isMiniPlayerCollapsed = false

        let rawText: String
        let title: String
        let language: String

        // 根据 isEnglishMode 决定播放内容
        if isEnglishMode,
           let engText = currentArticle.article_eng, !engText.isEmpty,
           let engTitle = currentArticle.topic_eng {
            rawText = engText
            title = engTitle
            language = "en-US"
        } else {
            rawText = currentArticle.article
            title = currentArticle.topic
            language = "zh-CN"
        }

        let paragraphs = rawText
            .components(separatedBy: .newlines)
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        let fullText = paragraphs.joined(separator: "\n\n")

        // 传入 language 参数
        audioPlayerManager.startPlayback(text: fullText, title: title, language: language)
    }

    private func updateUnreadCounts() {
        let sourceNameToUse: String?
        switch navigationContext {
        case .fromSource(let name):
            sourceNameToUse = name
        case .fromAllArticles:
            sourceNameToUse = nil
        }
        self.unreadCountForGroup = viewModel.getUnreadCountForDateGroup(
            timestamp: currentArticle.timestamp,
            inSource: sourceNameToUse
        )
        self.totalUnreadCountForContext = viewModel.getEffectiveUnreadCount(
            inSource: sourceNameToUse
        )
    }

    private func switchToNextArticleAndStopAudio() async {
        audioPlayerManager.stop()
        await switchToNextArticle(shouldAutoplayNext: false)
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) async {

        // 【新增】在这里调用 ReviewManager
        // 逻辑：用户决定看下一篇，说明刚刚这就这篇看完了/听完了，记录一次有效交互
        ReviewManager.shared.recordInteraction()

        if shouldAutoplayNext {
            audioPlayerManager.prepareForNextTransition()
        }

        _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        // 【优化】寻找下一篇文章的操作虽然很快，但在极大数据量下可能微卡
        // 由于 viewModel 是 MainActor，我们直接调用即可。
        // 关键在于：获取到 next 之后，不要立即做太重的同步操作
        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            await MainActor.run {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
                audioPlayerManager.stop()
            }
            return
        }

        // ... (图片下载逻辑保持不变) ...
        // 这里的图片下载已经是异步的，不会卡顿
        if !next.article.images.isEmpty {
             // ... 图片下载代码 ...
             let imagesAlreadyExist = resourceManager.checkIfImagesExistForArticle(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )

            if !imagesAlreadyExist {
                // 1. 设置下载状态的初始值
                await MainActor.run {
                    isDownloadingImages = true
                    downloadProgress = 0.0
                    downloadProgressText = Localized.imagePrepare // 使用词典：准备中
                }

                do {
                    // 2. 调用下载方法，并传入一个闭包来处理进度更新
                    try await resourceManager.downloadImagesForArticle(
                        timestamp: next.article.timestamp,
                        imageNames: next.article.images,
                        progressHandler: { current, total in
                            // 这个闭包会在 MainActor 上被调用，可以直接更新UI状态
                            self.downloadProgress = total > 0 ? Double(current) / Double(total) : 0
                            // 【修改】使用词典拼接：已下载 X / Y
                            self.downloadProgressText = "\(Localized.imageDownloaded) \(current) / \(total)"
                        }
                    )
                } catch {
                    await MainActor.run {
                        isDownloadingImages = false
                        // 移除这里的报错弹窗和音频停止逻辑
                    }
                    print("下一篇图片预下载失败，跳过等待继续切换: \(error.localizedDescription)")
                    // 移除原来的 return，让程序继续往下执行切换文章的逻辑！
                }


                // 3. 下载成功后，隐藏遮罩
                await MainActor.run {
                    isDownloadingImages = false
                }
            }
        }

        // --- 【核心修改开始】 ---

        // 移除原有的 "shouldKeepEnglish" 强制切换逻辑
        // 我们希望保留用户的“偏好设置”，即使当前文章没有英文，开关依然是开着的(只是显示中文)
        // 这样下一篇如果有英文，依然会自动显示英文。

        await MainActor.run {
            // 使用 easeInOut 动画，配合 LazyVStack，切换应该是丝滑的
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        }

        if shouldAutoplayNext {
            await MainActor.run {
                // 自动播放时，确保播放器是展开的
                self.isMiniPlayerCollapsed = false

                // 3. 根据全局 isEnglishMode 和当前文章是否有英文，决定播放语言
                let rawText: String
                let title: String
                let language: String

                // 动态判断当前这篇新文章能不能播英文
                let canPlayEnglish = self.isEnglishMode && 
                                     (next.article.article_eng != nil && !next.article.article_eng!.isEmpty)

                if canPlayEnglish,
                   let engText = next.article.article_eng, 
                   let engTitle = next.article.topic_eng {
                    // 播放英文
                    rawText = engText
                    title = engTitle
                    language = "en-US"
                } else {
                    // 播放中文
                    rawText = next.article.article
                    title = next.article.topic
                    language = "zh-CN"
                }

                let paragraphs = rawText
                    .components(separatedBy: .newlines)
                    .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                let fullText = paragraphs.joined(separator: "\n\n")

                // 【修复】明确传入 "zh-CN"，确保逻辑一致
                self.audioPlayerManager.startPlayback(text: fullText, title: title, language: language)
            }
        }
    }

    private func preDownloadNextArticleImages() async {
        print("开始检查并预下载下一篇文章的图片...")

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            print("没有找到下一篇未读文章，无需预下载。")
            return
        }

        guard !next.article.images.isEmpty else {
            print("下一篇文章 '\(next.article.topic)' 没有图片，无需预下载。")
            return
        }

        do {
            try await resourceManager.preDownloadImagesForArticleSilently(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )
        } catch {
            print("静默预下载下一篇文章的图片失败: \(error.localizedDescription)")
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }

    struct ToastView: View {
        let message: String
        var body: some View {
            Text(message)
                .font(.subheadline)
                .padding()
                .background(Color.black.opacity(0.75))
                .foregroundColor(.white)
                .cornerRadius(10)
                .padding(.bottom, 50)
                .transition(.opacity.animation(.easeInOut))
        }
    }
}

import SwiftUI

enum ArticleFilterMode: String, CaseIterable {
    case unread
    case read

    // 获取对应的本地化文本
    var localizedName: String {
        switch self {
        case .unread: return Localized.unread
        case .read: return Localized.read
        }
    }
}

// ==================== 公共协议和扩展 ====================
protocol ArticleListDataSource {
    var baseFilteredArticles: [ArticleItem] { get }
    var filterMode: ArticleFilterMode { get }
}

struct ArticleItem: Identifiable {
    let id: UUID
    let article: Article
    let sourceName: String?
    let sourceNameEN: String? // 【新增】
    var isContentMatch: Bool = false

    // 【修改】初始化方法
    init(article: Article, sourceName: String? = nil, sourceNameEN: String? = nil, isContentMatch: Bool = false) {
        self.id = article.id
        self.article = article
        self.sourceName = sourceName
        self.sourceNameEN = sourceNameEN // 【新增】
        self.isContentMatch = isContentMatch
    }
}

struct ArticleListContent: View {
    let items: [ArticleItem]
    let filterMode: ArticleFilterMode
    let expandedTimestamps: Set<String>
    let viewModel: NewsViewModel
    // 【新增】传入 AuthManager 以判断登录状态
    let authManager: AuthManager
    // 【新增】
    let showEnglish: Bool 
    let onToggleTimestamp: (String) -> Void
    let onArticleTap: (ArticleItem) async -> Void

    var groupedArticles: [String: [ArticleItem]] {
        let initial = Dictionary(grouping: items, by: { $0.article.timestamp })
        if filterMode == .read {
            return initial.mapValues { Array($0.reversed()) }
        } else {
            return initial
        }
    }

    var sortedTimestamps: [String] {
        // 【修改】统一将日期分组排序改为降序（新->旧）。
        // 这样未读列表也会将最新的日期显示在最上方。
        return groupedArticles.keys.sorted(by: >)
    }

    var body: some View {
        ForEach(sortedTimestamps, id: \.self) { timestamp in
            Section {
                if expandedTimestamps.contains(timestamp) {
                    ForEach(groupedArticles[timestamp] ?? []) { item in
                        // 【修改】将 authManager 传递下去
                        ArticleRowButton(
                            item: item,
                            filterMode: filterMode,
                            viewModel: viewModel,
                            authManager: authManager,
                            filteredArticles: items,
                            onTap: { await onArticleTap(item) },
                            // 【新增】传递参数
                            showEnglish: showEnglish 
                        )
                    }
                }
            } header: {
                // 【修改】锁定条件：未订阅 且 时间戳被锁定
                let isLocked = !authManager.isSubscribed && viewModel.isTimestampLocked(timestamp: timestamp)
                TimestampHeader(
                    timestamp: timestamp,
                    count: groupedArticles[timestamp]?.count ?? 0,
                    isExpanded: expandedTimestamps.contains(timestamp),
                    isLocked: isLocked, // 传递锁定状态
                    onToggle: { onToggleTimestamp(timestamp) }
                )
            }
        }
    }
}

