        } else if amount >= 1_000_000 {
            return String(format: "%.2fM", amount / 1_000_000)
        } else if amount >= 1_000 {
            return String(format: "%.2fK", amount / 1_000) // 改为保留两位小数
        } else {
            return String(format: "%.2f", amount) // 小额也保留两位小数
        }
    }


