    @State private var isAnimating = false

    var body: some View {
        ZStack {
            // 背景色
            Color(UIColor.systemGroupedBackground).ignoresSafeArea()

            GeometryReader { geo in
                // 1. 获取屏幕中心点
                let centerX = geo.size.width / 2
                let centerY = geo.size.height / 2

                // 2. 定义偏移量 (控制聚拢程度)
