                    MosaicCharacter(char: "股", colors: [.blue, .cyan, .mint])
                        .position(x: centerX + xOffset, y: centerY - yOffset)

                    // 左下：精 (紫色系) -> 中心向左下偏移
                    MosaicCharacter(char: "精", colors: [.purple, .indigo, .blue])
                        .position(x: centerX - xOffset, y: centerY + yOffset)

