    func fetchOptionsRankData() async -> ([OptionRankItem], [OptionRankItem])? {
        // 【安全修复】先在主线程安全获取阀值
        let limit = await MainActor.run { self.optionCapLimit }

        let urlString = "\(DatabaseManager.shared.serverBaseURL)/query/options_rank?limit=\(String(format: "%.0f", limit))"
        guard let url = URL(string: urlString) else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let result = try JSONDecoder().decode(OptionRankResponse.self, from: data)
            return (result.rank_up, result.rank_down)
        } catch {
            print("DataService: 获取期权榜单失败: \(error)")
            return nil
        }
    }

    // 【新增】在不修改服务器的情况下，客户端自行处理逻辑
    func fetchRecentEarningPriceIfNeeded(for symbol: String) {
        let upperSymbol = symbol.uppercased()

        // 性能优化：如果已经加载过，就不再重复请求
        if recentEarningPrices[upperSymbol] != nil { return }

        Task {
            // 1. 调用现有接口获取所有财报数据
            let earnings = await DatabaseManager.shared.fetchEarningData(forSymbol: symbol)

            // 2. 客户端排序：按日期从新到旧排序
            let sortedEarnings = earnings.sorted { $0.date > $1.date }

            // 3. 取出最新的一条
            guard let latest = sortedEarnings.first else { return }

            // 4. 判断日期是否在两个月内
            let calendar = Calendar.current
            let now = Date()
            if let twoMonthsAgo = calendar.date(byAdding: .month, value: -2, to: now) {
                // 如果最新财报日期 >= 两个月前的日期
                if latest.date >= twoMonthsAgo {
                    await MainActor.run {
                        self.recentEarningPrices[upperSymbol] = latest.price
                    }
                }
            }
        }
    }

    // 【新增】批量加载期权指标
    func fetchOptionsMetrics(for symbols: [String]) async {
        // 1. 过滤掉已经缓存过的，避免重复请求
        // 注意：在后台线程读取 MainActor 属性需要 await，或者我们简单点每次都请求也行，
        // 为了性能，建议简单过滤一下：
        let needFetch = await MainActor.run {
            symbols.filter { self.optionsMetricsCache[$0] == nil }
        }

        if needFetch.isEmpty { return }

        // 分批处理：一次最多查 50 个，防止 URL 过长
        let chunkedSymbols = needFetch.chunked(into: 50) 

        // 计算预期的交易日 (只需要计算一次)
        let expectedDateStr = TradingDateHelper.getLastExpectedTradingDateString()

        for chunk in chunkedSymbols {
            // 网络请求
            let results = await DatabaseManager.shared.fetchOptionsSummaries(forSymbols: chunk)

            // 处理数据
            // 1. 这里依然用 var，因为我们需要在下面的循环里修改它
            var tempCache: [String: (iv: String, sum: String)] = [:]

            for (symbol, summary) in results {
                // 校验日期
                if let serverDateStr = summary.date, serverDateStr == expectedDateStr,
                   let iv = summary.iv, let price = summary.price, let change = summary.change {

                    let sum = price + change
                    let sumStr = String(format: "%.2f", sum)
                    tempCache[symbol] = (iv, sumStr)
                }
            }

            // 【关键修改】
            // 在进入 MainActor 之前，创建一个不可变的副本 (let)
            // 这样编译器就知道这个数据在传递过程中不会被修改了
            let finalCache = tempCache

            // 回到主线程更新 UI
            await MainActor.run {
                // 这里使用 finalCache 而不是 tempCache
                self.optionsMetricsCache.merge(finalCache) { (_, new) in new }
            }
        }
    }

