    }

    // 修复 2：定义获取标题文字的函数（解决编译器超时问题）
    private func getFilterTitle(for mode: ArticleFilterMode) -> String {
        let name = mode.localizedName
        let count = getCount(for: mode)
        return "\(name) (\(count))"
    }

