    // MARK: - 检查图片是否存在而不下载
    func checkIfImagesExistForArticle(timestamp: String, imageNames: [String]) -> Bool {
        let sanitizedNames = imageNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        guard !sanitizedNames.isEmpty else {
            return true
        }

