                        viewModel: viewModel,
                        resourceManager: resourceManager,
                        autoPlayOnAppear: false // 【修改】适配新参数
                    )
                }
            }
            // 【修改点】原代码是 sourceName.replacingOccurrences...
            // 改为使用 displayTitle 属性
            .navigationTitle(displayTitle.replacingOccurrences(of: "_", with: " "))
