extension Color {
    // 稍微带一点灰度的背景，比纯白更护眼，能衬托出白色卡片
    static let viewBackground = Color(UIColor.systemGroupedBackground)

    // 卡片背景：浅色模式纯白，深色模式深灰
    static let cardBackground = Color(UIColor.secondarySystemGroupedBackground)
