    // 【新增】辅助函数：格式化显示时间文案
    private func formatUpdateTime(_ rawTime: String) -> String {
        // 如果是英文模式
        if isGlobalEnglishMode {
            return "Updated: \(rawTime)"
        } else {
            // 中文模式
            return "更新时间: \(rawTime)"
        }
    }

    // MARK: - 搜索结果视图 (使用新的卡片)
