            let upperSymbol = symbol.symbol.uppercased()
            updatedSymbol.value = compareMap[upperSymbol] ?? compareMap[symbol.symbol] ?? "N/A"
            updatedSymbol.tags = tagMap[upperSymbol]
            return updatedSymbol
        }
    }
