                return (filterMode == .unread) ? !isReadEff : isReadEff
            }
            // 【核心修改】这里传入 sourceNameEN
            .map { ArticleItem(article: $0.article, sourceName: $0.sourceName, sourceNameEN: $0.sourceNameEN) }
