    private func handlePurchase() {
        // 双重检查，虽然调用前通常已经检查过了
        guard authManager.isLoggedIn else {
            pendingAction = .purchase
            showLoginSheet = true
            return
        }

        // 2. 开始购买流程
        isPurchasing = true

        Task {
            do {
                // 【核心修改】获取购买结果 (true/false)
                let isSuccess = try await authManager.purchaseSubscription()

                await MainActor.run {
                    isPurchasing = false
                    pendingAction = .none // 结束后清空状态

                    if isSuccess {
                        // 只有明确成功时，才关闭页面
                        print("支付成功，关闭订阅页面")
                        dismiss()
                    }
                }
            } catch {
                await MainActor.run {
                    isPurchasing = false
                    pendingAction = .none
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }

    // 【修改】处理恢复购买：先检查登录
    private func performRestore() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            pendingAction = .restore
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有恢复逻辑
        isRestoring = true
        Task {
            do {
                try await authManager.restorePurchases()
                await MainActor.run {
                    isRestoring = false
                    pendingAction = .none
                    if authManager.isSubscribed {
                        restoreMessage = Localized.restoreSuccess
                    } else {
                        restoreMessage = Localized.restoreNotFound
                    }
                    showRestoreAlert = true
                }
            } catch {
                await MainActor.run {
                    isRestoring = false
                    pendingAction = .none
                    restoreMessage = "\(Localized.restoreFailed): \(error.localizedDescription)"
                    showRestoreAlert = true
                }
            }
        }
    }

    // 【修改】处理兑换逻辑：建议也加上登录检查
    private func handleRedeem() {
        guard !inviteCode.isEmpty else { return }

        // 确保已登录（理论上走到这里肯定是已登录的，因为弹窗前检查了）
        guard authManager.isLoggedIn else {
            pendingAction = .redeem
            showLoginSheet = true
            return
        }

        isRedeeming = true
        Task {
            // ... (原有兑换逻辑保持不变)
            do {
                try await authManager.redeemInviteCode(inviteCode)
                await MainActor.run {
                    isRedeeming = false
                    pendingAction = .none // 成功：清空挂起状态
                    inviteCode = ""
                    // 兑换成功后，直接关闭订阅页面
                    dismiss()
                }
            } catch {
                await MainActor.run {
                    isRedeeming = false
                    // 【关键修改点】
                    // 即使失败了，也清空 pendingAction。
                    // 因为此时兑换框已经弹出来了，用户的“登录并自动触发兑换”意图已经完成。
                    // 剩下的重试操作由用户在当前 Alert 界面手动完成即可。
                    pendingAction = .none 

                    inviteCode = ""
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }
}

