                .buttonStyle(PlainButtonStyle())

                Spacer()

                // 【修改】底部链接区域，加入恢复购买按钮
                HStack(spacing: 20) {
                    // 恢复购买按钮
                    Button(action: {
                        performRestore()
                    }) {
                        Text("恢复购买")
                            .font(.footnote)
                            .foregroundColor(.blue) // 链接通常用蓝色
                            .underline()
                    }
