        }
    }

    // 【修改】处理购买：先检查登录
    private func handlePurchase() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            // 未登录 -> 弹出登录页
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有购买逻辑
        isPurchasing = true
        Task {
            do {
                try await authManager.purchaseSubscription()
                await MainActor.run {
                    isPurchasing = false
                    // 【核心修改】
                    // 只有当订阅状态确实变为 true (购买成功) 时，才关闭弹窗。
                    // 如果用户取消了支付 (isSubscribed 仍为 false)，则不关闭，保留在当前页面。
                    if authManager.isSubscribed {
                        dismiss()
                    } else {
                        print("用户取消或未完成支付，保留订阅页面")
                    }
                }
            } catch {
                await MainActor.run {
                    isPurchasing = false
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }

    // 【修改】处理恢复购买：先检查登录
    private func performRestore() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            // 未登录 -> 弹出登录页
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有恢复逻辑
        isRestoring = true
        Task {
            do {
                // 调用 AuthManager 的恢复方法
                try await authManager.restorePurchases()
                await MainActor.run {
                    isRestoring = false
                    if authManager.isSubscribed {
                        restoreMessage = "成功恢复订阅！您现在可以无限制访问数据。"
                    } else {
                        restoreMessage = "未发现有效的订阅记录。"
                    }
                    showRestoreAlert = true
                }
            } catch {
                await MainActor.run {
                    isRestoring = false
                    restoreMessage = "恢复失败: \(error.localizedDescription)"
                    showRestoreAlert = true
                }
            }
        }
    }

    // 【新增】执行兑换码验证逻辑
    private func performRedeem() {
        // 简单的本地判空
        guard !redeemCodeInput.isEmpty else { return }

        // 2. 【新增】检查是否已登录 (如果服务器需要绑定User ID)
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        isRedeeming = true

        Task {
            do {
                // 调用 AuthManager 的方法请求服务器
                let success = try await authManager.redeemInviteCode(redeemCodeInput)

                await MainActor.run {
                    isRedeeming = false
                    if success {
                        redeemMessage = "验证成功！您已获得无限访问权限。"
                        redeemCodeInput = "" // 清空输入
                    }
                    showRedeemResultAlert = true
                }
            } catch {
                await MainActor.run {
                    isRedeeming = false
                    // 显示具体的错误信息（例如：无效的邀请码）
                    redeemMessage = "验证失败: \(error.localizedDescription)"
                    showRedeemResultAlert = true
                }
            }
        }
    }
}

import SwiftUI
import Foundation
import Network

class NetworkMonitor: ObservableObject {
    static let shared = NetworkMonitor()
    private let monitor = NWPathMonitor()
    private let queue = DispatchQueue(label: "NetworkMonitor")

    @Published var isWifi: Bool = false
    @Published var isConnected: Bool = false

    init() {
        monitor.pathUpdateHandler = { [weak self] path in
            DispatchQueue.main.async {
                self?.isConnected = path.status == .satisfied
                self?.isWifi = path.usesInterfaceType(.wifi)
            }
        }
        monitor.start(queue: queue)
    }
}

