                                    viewModel.toggleTimestampExpansion(for: sourceName, timestamp: timestamp)
                                },
                                onArticleTap: handleArticleTap
                            )
                        }
                    }
                    .listStyle(PlainListStyle())
                    // 【修复需求】修改 onAppear 逻辑：仅在首次进入时执行自动展开
                    .onAppear {
                        if !hasPerformedAutoExpansion {
                            autoExpandGroups()
