        }
        .onChange(of: scenePhase) { oldPhase, newPhase in
            // 获取 ViewModel 和 AuthManager 的引用
            let newsViewModel = appDelegate.newsViewModel
            let authManager = appDelegate.authManager

            if newPhase == .active {
                print("App is active. Syncing status...")

