let allYahooETFData = [];
const MAX_RETRIES = 3; // 定义最大重试次数

// 辅助函数：睡眠/等待
function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Function to update status in popup
function updatePopupStatus(text, logType = 'info', completed = false) {
