function normalizeVolume(raw) {
    if (!raw || typeof raw !== 'string') return '';
    let s = raw.trim().toUpperCase();
    let mul = 1;
    if (s.endsWith('B')) {
        mul = 1e9;
        s = s.slice(0, -1);
    } else if (s.endsWith('M')) {
        mul = 1e6;
        s = s.slice(0, -1);
    } else if (s.endsWith('K')) {
        mul = 1e3;
        s = s.slice(0, -1);
    }
    s = s.replace(/,/g, '');
    const n = parseFloat(s);
    if (isNaN(n)) return '';
    return Math.round(n * mul).toString();
}

