// 抓取 Kalshi 子页面 - 抓取 type, subtype 和所有 options
async function fetchKalshiSubpage(url) {
    try {
        const response = await fetch(url);
        const html = await response.text();

        // 使用 DOMParser 解析 HTML
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        // 提取 type 和 subtype
        const breadcrumbLinks = doc.querySelectorAll('a[href^="/category/"]');
        let type = '';
        let subtype = '';

        breadcrumbLinks.forEach((link, index) => {
            const span = link.querySelector('span.typ-body-x20, span[class*="typ-b"]');
            if (span) {
                const text = span.textContent.trim();
                if (index === 0) {
                    type = text;
                } else if (index === 1) {
                    subtype = text;
                }
            }
        });

        // 提取所有 options 和 values
        const options = [];

        // 查找所有包含选项的容器
        const optionContainers = doc.querySelectorAll('div[style*="flex: 1 1 0%"]');

        optionContainers.forEach(container => {
            // 查找选项名称
            const optionNameSpan = container.querySelector('span.typ-body-x30');
            if (!optionNameSpan) return;

            const optionNameDiv = optionNameSpan.querySelector('div');
            if (!optionNameDiv) return;

            const optionName = optionNameDiv.textContent.trim();

            // 查找对应的概率值
            const valueH2 = container.querySelector('h2.typ-headline-x10');
            if (!valueH2) return;

            const value = valueH2.textContent.trim();

            if (optionName && value) {
                options.push({
                    name: optionName,
                    value: value
                });
            }
        });

        return {
            type: type,
            subtype: subtype,
            options: options
        };
    } catch (error) {
        console.error('Error fetching Kalshi subpage:', error);
        return { type: '', subtype: '', options: [] };
    }
}

// 检测当前网站并更新UI
async function detectSite() {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    const url = tab.url;

    const siteInfo = document.getElementById('site-info');

    if (url.includes('polymarket.com')) {
        siteInfo.textContent = '当前网站: Polymarket';
        siteInfo.style.backgroundColor = '#e7f3ff';
        return 'polymarket';
    } else if (url.includes('kalshi.com')) {
        siteInfo.textContent = '当前网站: Kalshi';
        siteInfo.style.backgroundColor = '#fff3cd';
        return 'kalshi';
    } else {
        siteInfo.textContent = '不支持的网站';
        siteInfo.style.backgroundColor = '#f8d7da';
        return null;
    }
}

