// 打开新标签页并等待加载完成
function openTabAndWaitForLoad(url) {
    return new Promise((resolve, reject) => {
        chrome.tabs.create({ url, active: false }, (tab) => {
            if (chrome.runtime.lastError) {
                return reject(new Error(chrome.runtime.lastError.message));
            }

            const timeout = setTimeout(() => {
                chrome.tabs.onUpdated.removeListener(listener);
                resolve(tab);
            }, 20000);

            function listener(tabId, info) {
                if (tabId === tab.id && info.status === 'complete') {
                    chrome.tabs.onUpdated.removeListener(listener);
                    clearTimeout(timeout);
                    // 额外等待 React 渲染完成
                    setTimeout(() => resolve(tab), 3000);
                }
            }
            chrome.tabs.onUpdated.addListener(listener);
        });
    });
}

// 安全关闭标签页
function closeTab(tabId) {
    return new Promise((resolve) => {
        chrome.tabs.remove(tabId, () => {
            if (chrome.runtime.lastError) {
                console.warn('关闭标签页出错:', chrome.runtime.lastError.message);
            }
            resolve();
        });
    });
}

// 触发 JSON 文件下载
function downloadJson(data, filename) {
    const jsonData = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }, 100);
}

// 更新进度条
function updateProgress(current, total, itemName) {
    const container = document.getElementById('progressContainer');
    const fill = document.getElementById('progressBarFill');
    const text = document.getElementById('progressText');
    container.style.display = 'block';
    const pct = Math.round((current / total) * 100);
    fill.style.width = pct + '%';
    text.textContent = `(${current}/${total}) ${itemName}`;
}

function hideProgress() {
    document.getElementById('progressContainer').style.display = 'none';
}

// ============ 主入口 ============

async function startScraping() {
    const button = document.getElementById('scrapeBtn');
    const statusDiv = document.getElementById('status');
    const titleEl = document.getElementById('title');

    button.disabled = true;
    hideProgress();
    statusDiv.textContent = '正在自动检测网站...';
    statusDiv.className = 'info';

    try {
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        const url = tab.url;

        if (url.includes('polymarket.com')) {
            titleEl.textContent = 'Polymarket 数据抓取';
            await handlePolymarket(tab, statusDiv, button);
        } else if (url.includes('kalshi.com')) {
            titleEl.textContent = 'Kalshi 数据抓取';
            await handleKalshi(tab, statusDiv, button);
        } else {
            statusDiv.textContent = '请在 Polymarket 或 Kalshi 页面使用此扩展';
            statusDiv.className = 'error';
            button.disabled = false;
        }
    } catch (error) {
        statusDiv.textContent = '错误: ' + error.message;
        statusDiv.className = 'error';
        button.disabled = false;
        hideProgress();
    }
}

// ============ Polymarket 处理（保持原流程通过 background.js） ============

async function handlePolymarket(tab, statusDiv, button) {
    statusDiv.textContent = '正在抓取 Polymarket 数据...';

    const results = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: scrapePolymarketPageData
    });

    if (results && results[0] && results[0].result) {
        const data = results[0].result;
        chrome.runtime.sendMessage(
            { action: 'saveData', data: data, site: 'polymarket' },
            (response) => {
                if (response && response.success) {
                    statusDiv.textContent = `成功抓取 ${data.length} 条 Polymarket 数据!`;
                    statusDiv.className = 'success';
                } else {
                    statusDiv.textContent = '保存失败: ' + (response ? response.error : '未知错误');
                    statusDiv.className = 'error';
                }
                button.disabled = false;
                button.textContent = '重新抓取';
            }
        );
    } else {
        statusDiv.textContent = '未找到 Polymarket 数据';
        statusDiv.className = 'error';
        button.disabled = false;
    }
}

// ============ Kalshi 处理（打开子页面标签页抓取完整数据） ============

async function handleKalshi(mainTab, statusDiv, button) {
    try {
        // 第1步：抓取主页面基本信息（名称、子页面URL、交易量等）
        statusDiv.textContent = '正在抓取 Kalshi 主页面...';

        const mainResults = await chrome.scripting.executeScript({
            target: { tabId: mainTab.id },
            func: scrapeKalshiMainPageBasicInfo
        });

        if (!mainResults || !mainResults[0] || !mainResults[0].result || mainResults[0].result.length === 0) {
            statusDiv.textContent = '未找到 Kalshi 数据，请确认页面已加载完成';
            statusDiv.className = 'error';
            button.disabled = false;
            return;
        }

        const cards = mainResults[0].result;
        statusDiv.textContent = `找到 ${cards.length} 个项目，开始抓取子页面...`;
        statusDiv.className = 'info';

        const enrichedCards = [];

        // 第2步：逐个打开子页面，抓取完整 options
        for (let i = 0; i < cards.length; i++) {
            const card = cards[i];
            const shortName = card.name.length > 25 ? card.name.substring(0, 25) + '...' : card.name;
            statusDiv.textContent = `子页面 (${i + 1}/${cards.length}): ${shortName}`;
            updateProgress(i + 1, cards.length, shortName);

            let subTab = null;
            try {
                const subUrl = `https://kalshi.com${card.subUrl}`;
                subTab = await openTabAndWaitForLoad(subUrl);

                // 注入脚本：点击 "More markets" 按钮（如果存在）
                const clickResults = await chrome.scripting.executeScript({
                    target: { tabId: subTab.id },
                    func: clickKalshiMoreMarkets
                });

                const didClick = clickResults && clickResults[0] && clickResults[0].result;

                // 如果点击了展开按钮，等待新内容加载
                if (didClick) {
                    await new Promise(resolve => setTimeout(resolve, 3000));
                }

                // 注入脚本：抓取所有 option 和 value
                const subResults = await chrome.scripting.executeScript({
                    target: { tabId: subTab.id },
                    func: scrapeKalshiSubpageOptions
                });

                const subData = (subResults && subResults[0] && subResults[0].result)
                    ? subResults[0].result
                    : { type: '', subtype: '', options: [] };

                // 组装最终数据
                const result = {
                    name: card.name,
                    type: subData.type || card.fallbackType || '',
                    subtype: subData.subtype || card.fallbackSubtype || '',
                    volume: card.volume,
                    hide: "1"
                };

                // 子页面数据优先，主页面作为备选
                const options = (subData.options && subData.options.length > 0)
                    ? subData.options
                    : card.options;

                options.forEach((opt, index) => {
                    result[`option${index + 1}`] = opt.name;
                    result[`value${index + 1}`] = opt.value;
                });

                enrichedCards.push(result);

            } catch (err) {
                console.error(`子页面抓取失败 [${card.name}]:`, err);
                // 出错时使用主页面数据作为备选
                const result = {
                    name: card.name,
                    type: card.fallbackType || '',
                    subtype: card.fallbackSubtype || '',
                    volume: card.volume,
                    hide: "1"
                };
                card.options.forEach((opt, index) => {
                    result[`option${index + 1}`] = opt.name;
                    result[`value${index + 1}`] = opt.value;
                });
                enrichedCards.push(result);
            } finally {
                if (subTab) {
                    await closeTab(subTab.id);
                }
            }

            // 每个子页面之间稍作延迟，避免请求过快
            await new Promise(resolve => setTimeout(resolve, 500));
        }

        // 第3步：触发下载
        downloadJson(enrichedCards, 'kalshi.json');

        hideProgress();
        statusDiv.textContent = `成功抓取 ${enrichedCards.length} 条 Kalshi 数据（含子页面）!`;
        statusDiv.className = 'success';
        button.disabled = false;
        button.textContent = '重新抓取';

    } catch (error) {
        hideProgress();
        statusDiv.textContent = '错误: ' + error.message;
        statusDiv.className = 'error';
        button.disabled = false;
    }
}

// ============ 注入到 Kalshi 主页面的函数：获取卡片基本信息 ============

function scrapeKalshiMainPageBasicInfo() {
    const predictions = [];

    function cleanText(text) {
        return text.trim().replace(/\s+/g, ' ');
    }

    function capitalizeWords(str) {
        return str.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    }

    const cards = document.querySelectorAll('[data-testid="market-tile"]');

    cards.forEach(card => {
        try {
            const h2 = card.querySelector('h2');
            if (!h2) return;
            const name = cleanText(h2.textContent);

            const subLink = card.querySelector('a[href^="/markets/"]');
            if (!subLink) return;
            const subUrl = subLink.getAttribute('href');

            const categoryLink = card.querySelector('a[href^="/category/"]');
            let fallbackType = '';
            let fallbackSubtype = '';
            if (categoryLink) {
                const href = categoryLink.getAttribute('href') || '';
                fallbackSubtype = cleanText(categoryLink.textContent);
                const parts = href.replace('/category/', '').split('/');
                if (parts.length > 0 && parts[0]) {
                    fallbackType = capitalizeWords(parts[0]);
                }
            }

            let volume = '';
            const allSpans = card.querySelectorAll('span');
            for (const span of allSpans) {
                const t = span.textContent;
                if (t.includes('$') && t.toLowerCase().includes('vol')) {
                    volume = cleanText(t);
                    break;
                }
            }

            // 主页面上可见的 options（作为备选）
            const options = [];
            const optionRows = card.querySelectorAll('.col-span-full');
            optionRows.forEach(row => {
                const nameEl = row.querySelector('[class*="typ-body-x30"]');
                const button = row.querySelector('button[class*="stretched-link-action"]');
                let valueEl = button ? button.querySelector('span.tabular-nums') : null;
                if (nameEl && !valueEl) {
                    const specialButton = row.querySelector('button.rounded-x50[class*="stretched-link-action"]');
                    if (specialButton) {
                        valueEl = specialButton.querySelector('span.tabular-nums');
                    }
                }
                if (nameEl && valueEl) {
                    const valueText = cleanText(valueEl.textContent);
                    options.push({
                        name: cleanText(nameEl.textContent),
                        value: valueText.includes('%') ? valueText : valueText + '%'
                    });
                }
            });

            predictions.push({
                name: name,
                subUrl: subUrl,
                volume: volume,
                options: options,
                fallbackType: fallbackType,
                fallbackSubtype: fallbackSubtype
            });
        } catch (error) {
            console.error('处理 Kalshi 卡片出错:', error);
        }
    });

    return predictions;
}

// ============ 注入到 Kalshi 子页面的函数：点击 "More markets" ============

function clickKalshiMoreMarkets() {
    // 查找所有 span，寻找文本为 "More markets" 的元素
    const allSpans = document.querySelectorAll('span');
    for (const span of allSpans) {
        const text = span.textContent.trim().replace(/\s+/g, ' ');
        if (text === 'More markets') {
            // 向上查找可点击的父元素
            let target = span.closest('[role="button"]');
            if (!target) {
                let parent = span;
                for (let i = 0; i < 10; i++) {
                    parent = parent.parentElement;
                    if (!parent) break;
                    if (parent.getAttribute('role') === 'button' ||
                        parent.className.includes('cursor-pointer') ||
                        parent.tagName === 'BUTTON') {
                        target = parent;
                        break;
                    }
                }
            }
            if (target) {
                target.click();
                return true; // 成功点击
            }
        }
    }
    return false; // 未找到按钮（可能所有选项已显示）
}

// ============ 注入到 Kalshi 子页面的函数：抓取所有 options 和 values ============

function scrapeKalshiSubpageOptions() {
    const result = { type: '', subtype: '', options: [] };

    // 1. 抓取分类信息（面包屑 breadcrumb）
    const categoryLinks = document.querySelectorAll('a[href^="/category/"]');
    const categories = [];
    categoryLinks.forEach(link => {
        const text = link.textContent.trim().replace(/\s+/g, ' ');
        if (text && !categories.includes(text)) {
            categories.push(text);
        }
    });
    if (categories.length > 0) result.type = categories[0];
    if (categories.length > 1) result.subtype = categories[1];

    // 2. 抓取所有 option 名称和对应的 value
    //    名称在: <span class="...typ-body-x30..."><div ...>Name</div></span>
    //    值在:   <h2 class="...typ-headline-x10...">7%</h2>
    //    两者同在一个 div[style*="flex: 1 1"] 容器中

    const seen = new Set();

    // 先尝试在 section 中查找（限定范围，减少误匹配）
    const section = document.querySelector('section');
    const searchRoot = section || document;

    const nameElements = searchRoot.querySelectorAll('[class*="typ-body-x30"]');

    nameElements.forEach(nameEl => {
        const name = nameEl.textContent.trim().replace(/\s+/g, ' ');

        // 过滤掉非 option 文本
        if (!name) return;
        if (name.toLowerCase().includes('more market')) return;
        if (name.toLowerCase().includes('fewer market')) return;
        if (seen.has(name)) return;

        // 从 nameEl 向上遍历，找到同时包含 value (typ-headline-x10) 的最近容器
        let container = nameEl;
        let valueEl = null;
        for (let i = 0; i < 15; i++) {
            container = container.parentElement;
            if (!container) break;
            valueEl = container.querySelector('h2[class*="typ-headline-x10"]');
            if (valueEl) break;
        }

        const value = valueEl ? valueEl.textContent.trim() : '';
        seen.add(name);

        result.options.push({
            name: name,
            value: value
        });
    });

    return result;
}

// ============ Polymarket 主页面抓取函数（保持原逻辑不变） ============

function scrapePolymarketPageData() {
    const predictions = [];

    function cleanText(text) {
        return text.trim().replace(/\s+/g, ' ');
    }

    function getSlugFromUrl(url) {
        const match = url.match(/\/event\/([^/?]+)/);
        return match ? match[1] : null;
    }

    const cards = document.querySelectorAll('.grid > div > div[class*="flex"][class*="flex-col"][class*="rounded"]');

    cards.forEach(card => {
        try {
            const titleElement = card.querySelector('h2');
            if (!titleElement) return;
            const name = cleanText(titleElement.textContent);

            const eventLink = card.querySelector('a[href^="/event/"]');
            if (!eventLink) return;
            const slug = getSlugFromUrl(eventLink.getAttribute('href'));
            if (!slug) return;

            const volumeElement = card.querySelector('span.uppercase');
            const volume = volumeElement ? cleanText(volumeElement.textContent) : '';

            const optionElements = card.querySelectorAll('p.line-clamp-1[class*="text-body-base"]');

            if (optionElements.length > 0) {
                const options = [];
                const valueElements = card.querySelectorAll('p.text-\\[15px\\][class*="font-semibold"]');

                optionElements.forEach((optionEl, index) => {
                    const optionName = cleanText(optionEl.textContent);
                    const value = valueElements[index] ? cleanText(valueElements[index].textContent) : '';
                    options.push({ name: optionName, value: value });
                });

                predictions.push({
                    type: 'multi-option',
                    name: name,
                    slug: slug,
                    volume: volume,
                    options: options
                });
            } else {
                const valueElement = card.querySelector('p[class*="font-medium"][class*="text-heading-lg"]');
                const value = valueElement ? cleanText(valueElement.textContent) : '';

                predictions.push({
                    type: 'single-value',
                    name: name,
                    slug: slug,
                    volume: volume,
                    value: value
                });
            }
        } catch (error) {
            console.error('Error processing Polymarket card:', error);
        }
    });

    return predictions;
}

