function log(message, type = 'info') {
    const cls = {
        info: 'log-info', warn: 'log-warn', error: 'log-error',
        data: 'log-data', section: 'log-section', dim: 'log-dim'
    }[type] || '';
    const time = new Date().toLocaleTimeString();
