chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'saveData') {
        const site = request.site || 'polymarket';

        if (site === 'polymarket') {
            processPolymarketData(request.data)
                .then((processedData) => {
                    chrome.runtime.sendMessage({
                        type: 'downloadJson',
                        data: processedData,
                        filename: 'polymarket.json'
                    });
                    sendResponse({ success: true });
                })
                .catch(error => sendResponse({ success: false, error: error.message }));
            return true;
        }
    }
});

// ============ Polymarket 数据处理（保持原逻辑） ============
async function processPolymarketData(predictions) {
    const enrichedData = await Promise.all(
        predictions.map(async (pred) => {
            const subpageData = await fetchPolymarketSubpageData(pred.slug);

            if (pred.type === 'multi-option') {
                const result = {
                    name: pred.name,
                    type: subpageData.type,
                    subtype: subpageData.subtype,
                    volume: pred.volume,
                    enddate: subpageData.enddate,
                    hide: "1"
                };

                pred.options.forEach((opt, index) => {
                    result[`option${index + 1}`] = opt.name;
                    result[`value${index + 1}`] = opt.value;
                });

                return result;
            } else {
                return {
                    name: pred.name,
                    value: pred.value,
                    volume: pred.volume,
                    enddate: subpageData.enddate,
                    hide: "1"
                };
            }
        })
    );
    return enrichedData;
}

async function fetchPolymarketSubpageData(slug) {
    try {
        const response = await fetch(`https://polymarket.com/event/${slug}`);
        const html = await response.text();

        const typeMatch = html.match(/href="\/dashboards\/[^"]*">([^<]+)<\/a>/);
        const subtypeMatch = html.match(/href="\/predictions\/[^"]*">([^<]+)<\/a>/);
        const dateMatch = html.match(/<span[^>]*>(\w+ \d+, \d{4})<\/span>/);

        return {
            type: typeMatch ? typeMatch[1].trim() : '',
            subtype: subtypeMatch ? subtypeMatch[1].trim() : '',
            enddate: dateMatch ? dateMatch[1].trim() : ''
        };
    } catch (error) {
        console.error('Error fetching Polymarket subpage:', error);
        return { type: '', subtype: '', enddate: '' };
    }
}

// ============ 状态 ============
let mainTabId = null;
const params = new URLSearchParams(window.location.search);
mainTabId = parseInt(params.get('mainTabId'), 10);
const autoStart = params.get('auto') === '1';

// ============ DOM 引用 ============
const statusEl = document.getElementById('status');
const debugLogEl = document.getElementById('debugLog');
const progressContainer = document.getElementById('progressContainer');
const progressFill = document.getElementById('progressFill');
const progressText = document.getElementById('progressText');
const startBtn = document.getElementById('startBtn');
const clearBtn = document.getElementById('clearBtn');

// ============ 日志工具 ============
function log(message, type = 'info') {
    const cls = {
        info: 'log-info', warn: 'log-warn', error: 'log-error',
        data: 'log-data', section: 'log-section', dim: 'log-dim'
    }[type] || '';
    const time = new Date().toLocaleTimeString();
    const span = document.createElement('span');
    span.className = cls;
    span.textContent = '[' + time + '] ' + message + '\n';
    debugLogEl.appendChild(span);
    debugLogEl.scrollTop = debugLogEl.scrollHeight;
}

function setStatus(text, type = 'info') {
    statusEl.textContent = text;
    statusEl.className = 'status-box status-' + type;
}

function updateProgress(current, total, name) {
    progressContainer.style.display = 'block';
    progressFill.style.width = Math.round((current / total) * 100) + '%';
    progressText.textContent = '(' + current + '/' + total + ') ' + name;
}

// ============ 标签页管理 ============

// 创建前台标签页（active:true 是绕过 Cloudflare 的关键）
function createTab(url) {
    return new Promise(function (resolve, reject) {
        chrome.tabs.create({ url: url, active: true }, function (tab) {
            if (chrome.runtime.lastError) {
                reject(new Error(chrome.runtime.lastError.message));
            } else {
                resolve(tab);
            }
        });
    });
}

// 等待标签页 status: complete
function waitForTabComplete(tabId, timeoutMs) {
    if (!timeoutMs) timeoutMs = 30000;
    return new Promise(function (resolve) {
        var timeout = setTimeout(function () {
            chrome.tabs.onUpdated.removeListener(listener);
            resolve(false);
        }, timeoutMs);

        function listener(id, info) {
            if (id === tabId && info.status === 'complete') {
                chrome.tabs.onUpdated.removeListener(listener);
                clearTimeout(timeout);
                resolve(true);
            }
        }
        chrome.tabs.onUpdated.addListener(listener);
    });
}

// 智能轮询：检测到页面内容后立即返回，不再固定等待
async function pollForContent(tabId, maxMs) {
    if (!maxMs) maxMs = 18000;
    var start = Date.now();
    while (Date.now() - start < maxMs) {
        try {
            var r = await chrome.scripting.executeScript({
                target: { tabId: tabId },
                func: function () {
                    var opts = document.querySelectorAll('[class*="typ-body-x30"]');
                    var isBotPage = !!document.getElementById('challenge-form') ||
                        !!document.querySelector('.cf-browser-verification') ||
                        document.title.toLowerCase().includes('just a moment') ||
                        !!document.querySelector('[id*="turnstile"]');
                    return {
                        hasContent: opts.length > 0,
                        optionCount: opts.length,
                        isBotPage: isBotPage
                    };
                }
            });
            var c = r && r[0] && r[0].result;
            if (c && c.hasContent) {
                // 额外等 300ms 让剩余元素渲染完
                await new Promise(function (res) { setTimeout(res, 300); });
                return { ready: true, isBotPage: false, elapsed: Date.now() - start, optionCount: c.optionCount };
            }
            if (c && c.isBotPage) {
                // 反爬虫页面，慢速轮询
                await new Promise(function (res) { setTimeout(res, 2000); });
            } else {
                // 正常等待渲染，快速轮询
                await new Promise(function (res) { setTimeout(res, 400); });
            }
        } catch (e) {
            await new Promise(function (res) { setTimeout(res, 500); });
        }
    }
    return { ready: false, isBotPage: true, elapsed: Date.now() - start, optionCount: 0 };
}

// 点击 More markets 后轮询等待选项增多
async function pollForMoreOptions(tabId, prevCount, maxMs) {
    if (!maxMs) maxMs = 5000;
    var start = Date.now();
    while (Date.now() - start < maxMs) {
        try {
            var r = await chrome.scripting.executeScript({
                target: { tabId: tabId },
                func: function () {
                    return document.querySelectorAll('[class*="typ-body-x30"]').length;
                }
            });
            var count = r && r[0] && r[0].result;
            if (count && count > prevCount) {
                await new Promise(function (res) { setTimeout(res, 300); });
                return { expanded: true, elapsed: Date.now() - start };
            }
        } catch (e) { /* ignore */ }
        await new Promise(function (res) { setTimeout(res, 300); });
    }
    return { expanded: false, elapsed: Date.now() - start };
}

function closeTab(tabId) {
    return new Promise(function (resolve) {
        chrome.tabs.remove(tabId, function () {
            if (chrome.runtime.lastError) {
                log('  ⚠️ 关闭标签失败: ' + chrome.runtime.lastError.message, 'warn');
            }
            resolve();
        });
    });
}

// ============ 下载工具 ============

// 增量保存：用 chrome.downloads API 覆盖写入同名文件
var lastIncrDownloadId = null;

function incrementalSave(data, filename) {
    try {
        var jsonStr = JSON.stringify(data, null, 2);
        var blob = new Blob([jsonStr], { type: 'application/json' });
        var blobUrl = URL.createObjectURL(blob);
        chrome.downloads.download({
            url: blobUrl,
            filename: filename,
            conflictAction: 'overwrite',
            saveAs: false
        }, function (downloadId) {
            if (chrome.runtime.lastError) {
                log('  ⚠️ 增量保存失败: ' + chrome.runtime.lastError.message, 'warn');
            }
            lastIncrDownloadId = downloadId;
            setTimeout(function () { URL.revokeObjectURL(blobUrl); }, 5000);
        });
    } catch (e) {
        log('  ⚠️ 增量保存异常: ' + e.message, 'warn');
    }
}

// 最终下载（备用，使用 <a> 标签）
function downloadJson(data, filename) {
    var blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
}

