async function handlePolymarket(tab, statusDiv, button) {
    statusDiv.textContent = '正在抓取 Polymarket 数据...';

    const results = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: scrapePolymarketPageData
    });

