// ============ Polymarket 初始化和过滤器设置 ============

async function initializePolymarketPage(tab, statusDiv) {
    statusDiv.textContent = '正在初始化 Polymarket 页面...';

    // 步骤1: 等待页面加载完成
    await new Promise(resolve => setTimeout(resolve, 2000));

    // 步骤2: 点击过滤器图标 (sliders icon)
    statusDiv.textContent = '正在打开过滤器...';
    const filterResult = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: clickFilterIcon
    });

    if (!filterResult || !filterResult[0]?.result) {
        throw new Error('未找到过滤器图标');
    }

    await new Promise(resolve => setTimeout(resolve, 1000));

    // 步骤3: 点击 "24hr Volume" 下拉菜单
    statusDiv.textContent = '正在打开排序菜单...';
    const volumeDropdownResult = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: clickVolumeDropdown
    });

    if (!volumeDropdownResult || !volumeDropdownResult[0]?.result) {
        throw new Error('未找到 24hr Volume 菜单');
    }

    // 增加等待时间，确保菜单完全展开
    await new Promise(resolve => setTimeout(resolve, 1500));

    // 步骤4: 选择 "Total Volume" (带重试机制)
    statusDiv.textContent = '正在选择 Total Volume...';

    let totalVolumeResult = null;
    for (let retry = 0; retry < 3; retry++) {
        if (retry > 0) {
            console.log(`重试第 ${retry} 次...`);
            await new Promise(resolve => setTimeout(resolve, 1000));
        }

        totalVolumeResult = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: selectTotalVolume
        });

        if (totalVolumeResult && totalVolumeResult[0]?.result) {
            break;
        }
    }

    if (!totalVolumeResult || !totalVolumeResult[0]?.result) {
        throw new Error('未找到 Total Volume 选项（已重试3次）');
    }

    await new Promise(resolve => setTimeout(resolve, 1500));
    statusDiv.textContent = '页面初始化完成,准备抓取数据...';
}

// 注入函数: 点击过滤器图标
function clickFilterIcon() {
    const buttons = Array.from(document.querySelectorAll('button[aria-label="Toggle filters"]'));

    for (const button of buttons) {
        const svg = button.querySelector('svg title');
        if (svg && svg.textContent === 'sliders') {
            button.click();
            return true;
        }
    }

    // 备选方案: 通过SVG路径查找
    const allButtons = Array.from(document.querySelectorAll('button'));
    for (const button of allButtons) {
        const svg = button.querySelector('svg[viewBox="0 0 18 18"]');
        if (svg) {
            const circles = svg.querySelectorAll('circle');
            if (circles.length === 2) { // sliders icon 有两个圆圈
                button.click();
                return true;
            }
        }
    }

    return false;
}

// 注入函数: 点击 Volume 下拉菜单 (显示 "24hr Volume")
function clickVolumeDropdown() {
    // 查找包含 "24hr Volume" 文本的按钮
    const buttons = Array.from(document.querySelectorAll('button'));

    for (const button of buttons) {
        const text = button.textContent.trim();
        if (text.includes('24hr Volume') || text.includes('24Hr Volume') || text.includes('Total Volume')) {
            button.click();
            return true;
        }
    }

    // 备选: 查找包含上升箭头图标的按钮
    for (const button of buttons) {
        const polyline = button.querySelector('polyline[points*="11.25 5.75"]');
        if (polyline) {
            button.click();
            return true;
        }
    }

    // 备选: 查找包含火焰SVG的按钮
    for (const button of buttons) {
        const svg = button.querySelector('svg');
        if (svg) {
            const paths = svg.querySelectorAll('path');
            if (paths.length >= 2) {
                const text = button.textContent.toLowerCase();
                if (text.includes('volume')) {
                    button.click();
                    return true;
                }
            }
        }
    }

    return false;
}

// 注入函数: 选择 "Total Volume" - 简化版
function selectTotalVolume() {
    console.log('开始查找 Total Volume...');

    // 最直接的方法：查找所有菜单项，点击第二个
    const menuItems = Array.from(document.querySelectorAll('[role="menuitem"]'));
