                (target.className && target.className.includes('cursor-pointer'))) {
                target.click();
                d.push('Clicked element directly');
                clicked = true;
                break;
            }

            // 向上查找可点击的父元素
            var parent = target;
            for (var j = 0; j < 10; j++) {
