        log('', 'dim');
        cards.forEach(function (c, i) {
            log('  [' + i + '] "' + c.name + '"  |  volume: ' + c.volume, 'data');
            log('       subUrl: ' + c.subUrl + '  主页面options: ' + c.options.length + '个', 'dim');
        });

