  startScraping();

  async function startScraping() {
    try {
      // 重置状态
      allResults = [];
      progressBar.style.width = '0%';
      logContainer.innerHTML = ''; // 清空旧日志
      statusDiv.textContent = `Starting scrape... (0/${urls.length})`;
      logMessage(`初始化... 准备抓取 ${urls.length} 个页面。`);

      // 按顺序处理所有URL
      for (let i = 0; i < urls.length; i++) {
