                .buttonStyle(PlainButtonStyle())

                Spacer()

                // 底部链接区域
                HStack(spacing: 20) {
                    // 恢复购买按钮
                    Button(action: {
                        // 【修改 3】恢复购买逻辑优化
                        if authManager.isLoggedIn {
                            performRestore()
                        } else {
                            pendingAction = .restore
