@MainActor
class ResourceManager: ObservableObject {

    @Published var isSyncing = false
    // 【修改】初始值使用双语
    @Published var syncMessage = Localized.syncStarting 
    @Published var isDownloading = false
    @Published var downloadProgress: Double = 0.0
    @Published var progressText = ""
    @Published var showAlreadyUpToDateAlert = false

    // 【新增】强制更新控制开关
    @Published var showForceUpdate: Bool = false
    @Published var appStoreURL: String = ""

    // 【新增】存储最后更新时间，默认为空
    @Published var serverUpdateTime: String = "" 

    // 【新增】存储从服务器获取的配置
    @Published var serverLockedDays: Int = 0
    @Published var sourceMappings: [String: String] = [:]

    // 【新增】当前需要显示的通知（如果为 nil 则不显示）
    @Published var activeNotification: String? = nil

    @Published var serverDate: String = "" // 【新增】存储服务器日期

    private let serverBaseURL = "http://106.15.183.158:5001/api/ONews"
    // 【新增】UserDefaults Key
    private let dismissedNotificationKey = "dismissedNotificationContent"

    private let fileManager = FileManager.default
    private var documentsDirectory: URL {
        fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    // 【核心修改 1】配置 URLSession
    private let urlSession: URLSession = {
        let configuration = URLSessionConfiguration.default
        // 1. 请求超时时间 (连接服务器的时间)
        configuration.timeoutIntervalForRequest = 5.0
        // 2. 资源超时时间 (整个下载过程的时间)
        configuration.timeoutIntervalForResource = 30.0
        // 3. 【关键】设置为 false。如果没网，立即报错，不要傻等。
        configuration.waitsForConnectivity = false
        return URLSession(configuration: configuration)
    }()

    // 【新增】网络监视器
    private let networkMonitor = NWPathMonitor()
    private let monitorQueue = DispatchQueue(label: "NetworkMonitor")
    @Published var isWifiConnected: Bool = false
    // 【新增】增加一个通用的网络可用性标记
    @Published var isNetworkAvailable: Bool = true

    // ✅ 修复 1: 去掉 override 关键字
    init() {
        // 启动网络监听
        networkMonitor.pathUpdateHandler = { [weak self] path in
            DispatchQueue.main.async {
                self?.isWifiConnected = path.usesInterfaceType(.wifi)
                // 只要有网（WiFi或蜂窝）都算可用
                self?.isNetworkAvailable = path.status == .satisfied
            }
        }
        networkMonitor.start(queue: monitorQueue)
    }

    deinit {
        networkMonitor.cancel()
    }

    // 【新增】网络检查辅助函数
    private func ensureNetworkReachable() throws {
        if !isNetworkAvailable {
            throw URLError(.notConnectedToInternet)
        }
    }

    // 【修改】特效数据获取失败时的默认词汇
    func fetchSourceNames() async -> [String] {
        do {
            // 复用已有的 getServerVersion 方法
            let version = try await getServerVersion()
            // 提取 source_mappings 的所有 value（即中文名称）
            if let mappings = version.source_mappings {
                let names = Array(mappings.values)
                return names
            }
        } catch {
            print("特效数据获取失败: \(error)")
        }
        // 使用双语字典中的默认词汇
        return [
            Localized.fallbackSource1,
            Localized.fallbackSource2,
            Localized.fallbackSource3,
            Localized.fallbackSource4,
            Localized.fallbackSource5,
            Localized.fallbackSource6
        ]
    }

    // MARK: - 检查图片是否存在而不下载
    func checkIfImagesExistForArticle(timestamp: String, imageNames: [String]) -> Bool {
        let sanitizedNames = imageNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        guard !sanitizedNames.isEmpty else {
            return true
        }

        let directoryName = "news_images_\(timestamp)"
        let localDirectoryURL = documentsDirectory.appendingPathComponent(directoryName)

        for imageName in sanitizedNames {
            let localImageURL = localDirectoryURL.appendingPathComponent(imageName)
            if !fileManager.fileExists(atPath: localImageURL.path) {
                print("检查发现图片缺失: \(imageName)")
                return false
            }
        }

        print("检查发现所有图片均已本地存在。")
        return true
    }

    // 【新增】处理通知的逻辑
    // 当从服务器获取到新版本信息时调用此方法
    private func updateNotificationStatus(serverMessage: String?) {
        // 1. 如果服务器没有通知，直接清空
        guard let message = serverMessage, !message.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            self.activeNotification = nil
            return
        }

        // 2. 获取本地已关闭过的通知内容
        let dismissedMessage = UserDefaults.standard.string(forKey: dismissedNotificationKey)

        // 3. 只有当服务器通知内容 不等于 本地已关闭的内容时，才显示
        // 这样一旦内容变更（不相等），就会再次弹出
        if message != dismissedMessage {
            self.activeNotification = message
        } else {
            self.activeNotification = nil
        }
    }

    // 【新增】用户点击关闭按钮时调用
    func dismissNotification() {
        guard let message = activeNotification else { return }

        // 1. 保存当前内容到本地，标记为“已读/已关闭”
        UserDefaults.standard.set(message, forKey: dismissedNotificationKey)

        // 2. 隐藏 UI
        withAnimation {
            self.activeNotification = nil
        }
    }

    // MARK: - 按需下载单篇文章的图片 (面向UI)
    // 【核心修改】为函数增加一个 progressHandler 回调闭包
    func downloadImagesForArticle(
        timestamp: String,
        imageNames: [String],
        progressHandler: @escaping @MainActor (Int, Int) -> Void
    ) async throws {
        // 【核心修改 2】下载前先检查网络，如果是离线，直接抛出错误，触发 UI 层的降级逻辑
        try ensureNetworkReachable()
        let sanitizedNames = imageNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        var uniqueNames: [String] = []
        var seen = Set<String>()
        for name in sanitizedNames {
            if !seen.contains(name) {
                uniqueNames.append(name)
                seen.insert(name)
            }
        }

        guard !uniqueNames.isEmpty else { return }

        let directoryName = "news_images_\(timestamp)"
        let localDirectoryURL = documentsDirectory.appendingPathComponent(directoryName)

        try? fileManager.createDirectory(at: localDirectoryURL, withIntermediateDirectories: true)

        var imagesToDownload: [String] = []
        for imageName in uniqueNames {
            let localImageURL = localDirectoryURL.appendingPathComponent(imageName)
            if !fileManager.fileExists(atPath: localImageURL.path) {
                imagesToDownload.append(imageName)
            }
        }

        guard !imagesToDownload.isEmpty else {
            print("所有图片已存在，无需下载")
            return
        }

        let totalToDownload = imagesToDownload.count
        print("需要下载 \(totalToDownload) 张图片")

        // 【修改】在下载开始前，立即调用一次回调，用于初始化UI
        progressHandler(0, totalToDownload)

        for (index, imageName) in imagesToDownload.enumerated() {
            let downloadPath = "\(directoryName)/\(imageName)"
            guard var components = URLComponents(string: "\(serverBaseURL)/download") else { continue }
            components.queryItems = [URLQueryItem(name: "filename", value: downloadPath)]
            guard let url = components.url else { continue }

            do {
                let (tempURL, response) = try await urlSession.download(from: url)

                guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                    // 如果是 404 等服务器错误，抛出异常
                    throw URLError(.badServerResponse)
                }

                let destinationURL = localDirectoryURL.appendingPathComponent(imageName)
                if fileManager.fileExists(atPath: destinationURL.path) {
                    try fileManager.removeItem(at: destinationURL)
                }
                try fileManager.moveItem(at: tempURL, to: destinationURL)

                // 【修改】每成功下载一张图片，就调用回调函数更新进度
                // `index + 1` 表示当前已完成的数量
                let completedCount = index + 1
                progressHandler(completedCount, totalToDownload)
                print("✅ 已下载图片 (\(completedCount)/\(totalToDownload)): \(imageName)")

            } catch {
                print("⚠️ 下载图片失败 \(imageName): \(error.localizedDescription)")
                // 【关键】这里抛出错误，让上层捕获。
                // 如果是网络断开，urlSession 现在会立即抛出错误
                throw error
            }
        }
    }

    // MARK: - 静默预下载单篇文章的图片 (后台任务)
    func preDownloadImagesForArticleSilently(timestamp: String, imageNames: [String]) async throws {
        let sanitizedNames = imageNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        var uniqueNames: [String] = []
        var seen = Set<String>()
        for name in sanitizedNames {
            if !seen.contains(name) {
                uniqueNames.append(name)
                seen.insert(name)
            }
        }

        guard !uniqueNames.isEmpty else { return }

        let directoryName = "news_images_\(timestamp)"
        let localDirectoryURL = documentsDirectory.appendingPathComponent(directoryName)

        try? fileManager.createDirectory(at: localDirectoryURL, withIntermediateDirectories: true)

        var imagesToDownload: [String] = []
        for imageName in uniqueNames {
            let localImageURL = localDirectoryURL.appendingPathComponent(imageName)
            if !fileManager.fileExists(atPath: localImageURL.path) {
                imagesToDownload.append(imageName)
            }
        }

        guard !imagesToDownload.isEmpty else {
            print("[静默预载] 所有目标图片已存在，无需下载。")
            return
        }

        print("[静默预载] 发现 \(imagesToDownload.count) 张需要预下载的图片。")

        for (index, imageName) in imagesToDownload.enumerated() {
            let downloadPath = "\(directoryName)/\(imageName)"
            guard var components = URLComponents(string: "\(serverBaseURL)/download") else { continue }
            components.queryItems = [URLQueryItem(name: "filename", value: downloadPath)]
            guard let url = components.url else { continue }

            do {
                let (tempURL, response) = try await urlSession.download(from: url)

                guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                    throw URLError(.badServerResponse)
                }

                let destinationURL = localDirectoryURL.appendingPathComponent(imageName)
                if fileManager.fileExists(atPath: destinationURL.path) {
                    try fileManager.removeItem(at: destinationURL)
                }
                try fileManager.moveItem(at: tempURL, to: destinationURL)
                print("✅ [静默预载] 成功 (\(index + 1)/\(imagesToDownload.count)): \(imageName)")

            } catch {
                print("⚠️ [静默预载] 失败 \(imageName): \(error.localizedDescription)")
                throw error
            }
        }
    }

    // MARK: - 【新增】批量离线下载所有图片
    func downloadAllOfflineImages(progressHandler: @escaping @MainActor (Int, Int) -> Void) async throws {
        // ✅ 修复 2: 在主线程获取 URL，因为 documentsDirectory 是 @MainActor 隔离的
        let docDir = self.documentsDirectory

        // 2. 遍历 JSON，解析出所有需要的图片
        // ✅ 修复 3: 使用捕获列表 [docDir] 将 URL 传入后台任务
        // ✅ 修复 4: 在后台任务中使用 FileManager.default，而不是 self.fileManager
        let allImagesToDownload = await Task.detached(priority: .userInitiated) { [docDir] in
            let fm = FileManager.default // 使用本地实例
            var tasks: [(urlPath: String, localPath: URL)] = []

            // 获取本地所有 onews_*.json 文件
            guard let localFiles = try? fm.contentsOfDirectory(at: docDir, includingPropertiesForKeys: nil) else {
                return tasks
            }

            let jsonFiles = localFiles.filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }
            let decoder = JSONDecoder()

            for fileURL in jsonFiles {
                guard let data = try? Data(contentsOf: fileURL),
                      let articlesMap = try? decoder.decode([String: [Article]].self, from: data) else {
                    continue
                }

                // 提取时间戳 (例如 onews_260131.json -> 260131)
                let filename = fileURL.deletingPathExtension().lastPathComponent
                let timestamp = filename.replacingOccurrences(of: "onews_", with: "")
                let directoryName = "news_images_\(timestamp)"

                // 扁平化所有文章的所有图片
                let allArticles = articlesMap.values.flatMap { $0 }
                let allImageNames = allArticles.flatMap { $0.images }

                // 去重
                let uniqueImages = Set(allImageNames)

                for imageName in uniqueImages {
                    let cleanName = imageName.trimmingCharacters(in: .whitespacesAndNewlines)
                    if cleanName.isEmpty { continue }

                    // 构造下载路径和本地保存路径
                    // 服务器路径格式: news_images_260131/xxx.jpg
                    let downloadPath = "\(directoryName)/\(cleanName)"
                    let localDir = docDir.appendingPathComponent(directoryName)
                    let localFile = localDir.appendingPathComponent(cleanName)

                    // 检查本地是否已存在
                    if !fm.fileExists(atPath: localFile.path) {
                        try? fm.createDirectory(at: localDir, withIntermediateDirectories: true)
                        tasks.append((urlPath: downloadPath, localPath: localFile))
                    }
                }
            }
            return tasks
        }.value // 等待后台任务完成

        // 3. 开始下载
        let total = allImagesToDownload.count
        if total == 0 {
            print("所有图片均已离线缓存，无需下载。")
            progressHandler(0, 0)
            return
        }

        print("开始离线下载，共缺 \(total) 张图片...")
        progressHandler(0, total)

        for (index, task) in allImagesToDownload.enumerated() {
            guard var components = URLComponents(string: "\(serverBaseURL)/download") else { continue }
            components.queryItems = [URLQueryItem(name: "filename", value: task.urlPath)]
            guard let url = components.url else { continue }

            do {
                let (tempURL, response) = try await urlSession.download(from: url)

                guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                    // 如果单张失败，打印日志但不中断整个流程
                    print("⚠️ 下载失败: \(task.urlPath)")
                    continue
                }

                // 移动文件 (回到主线程操作文件是安全的，或者这里使用 fileManager 也可以，因为是串行)
                if fileManager.fileExists(atPath: task.localPath.path) {
                    try fileManager.removeItem(at: task.localPath)
                }
                try fileManager.moveItem(at: tempURL, to: task.localPath)

                // 更新进度
                progressHandler(index + 1, total)

            } catch {
                print("⚠️ 下载异常: \(task.urlPath) - \(error.localizedDescription)")
            }
        }
    }

    func checkAndDownloadAllNewsManifests(isManual: Bool = false) async throws {
        self.isSyncing = true
        self.isDownloading = false
        self.syncMessage = Localized.fetchingManifest // 【修改】
        self.progressText = ""
        self.downloadProgress = 0.0

        do {
            let serverVersion = try await getServerVersion()

            // 【新增】获取到配置后，立即更新
            self.serverLockedDays = serverVersion.locked_days ?? 0

            let allJsonInfos = serverVersion.files
                .filter { $0.type == "json" && $0.name.starts(with: "onews_") }
                .sorted { $0.name < $1.name }

            if allJsonInfos.isEmpty {
                self.isSyncing = false
                return
            }

            var tasksToDownload: [FileInfo] = []
            for jsonInfo in allJsonInfos {
                let localURL = documentsDirectory.appendingPathComponent(jsonInfo.name)
                var shouldDownload = false

                if fileManager.fileExists(atPath: localURL.path) {
                    if let serverMD5 = jsonInfo.md5, let localMD5 = calculateMD5(for: localURL) {
                        if serverMD5 != localMD5 {
                            print("MD5不匹配，需要更新: \(jsonInfo.name)")
                            shouldDownload = true
                        } else {
                            print("已是最新: \(jsonInfo.name)")
                        }
                    } else {
                        print("缺少MD5，强制重新下载: \(jsonInfo.name)")
                        shouldDownload = true
                    }
                } else {
                    print("本地不存在，准备下载: \(jsonInfo.name)")
                    shouldDownload = true
                }

                if shouldDownload {
                    tasksToDownload.append(jsonInfo)
                }
            }

            if tasksToDownload.isEmpty {
                if isManual {
                    self.isSyncing = false
                    self.showAlreadyUpToDateAlert = true
                } else {
                    self.isSyncing = false
                }
                return
            }

            self.isDownloading = true
            let total = tasksToDownload.count
            for (index, info) in tasksToDownload.enumerated() {
                self.progressText = "\(index + 1)/\(total)"
                self.downloadProgress = Double(index + 1) / Double(total)
                self.syncMessage = Localized.downloadingData // 【修改】
                try await downloadSingleFile(named: info.name)
            }

            self.isDownloading = false
            // self.syncMessage = "新闻源已准备就绪！\n\n请点击右下角“+”按钮。"
            self.progressText = ""
            resetStateAfterDelay()

        } catch {
            self.isSyncing = false
            self.isDownloading = false
            throw error
        }
    }

    func checkAndDownloadUpdates(isManual: Bool = false) async throws {
        // 【核心修改 3】如果是自动同步且没网，直接静默返回，不要转圈
        if !isManual && !isNetworkAvailable {
            print("自动同步：检测到无网络，跳过同步，使用本地数据。")
            return
        }

        // 如果是手动同步且没网，ensureNetworkReachable 会抛错，UI层会弹窗提示
        if isManual {
            try ensureNetworkReachable()
        }

        self.isSyncing = true
        self.isDownloading = false
        self.syncMessage = Localized.checkingUpdates
        self.progressText = ""
        self.downloadProgress = 0.0

        // 使用 defer 确保 isSyncing 最终关闭
        // 这防止了 UI 永久卡死在 loading 状态
        defer {
            Task { @MainActor in
                // 注意：这里不要立即设为 false，否则弹窗还没出来 loading 就没了
                // 我们会在 resetStateAfterDelay 里处理
                if !self.showAlreadyUpToDateAlert {
                    self.isSyncing = false
                }
            }
        }

        do {
            let serverVersion = try await getServerVersion()
            let localFiles = try getLocalFiles()

            // 【新增】获取到配置后，立即更新
            self.serverLockedDays = serverVersion.locked_days ?? 0
            print("ResourceManager: 从服务器获取到 locked_days = \(self.serverLockedDays)")

            self.syncMessage = Localized.cleaningOldResources // 【修改】
            let validServerFiles = Set(serverVersion.files.map { $0.name })
            let filesToDelete = localFiles.subtracting(validServerFiles)
            let oldNewsItemsToDelete = filesToDelete.filter {
                $0.starts(with: "onews_") || $0.starts(with: "news_images_")
            }

            if !oldNewsItemsToDelete.isEmpty {
                print("发现需要清理的过时资源: \(oldNewsItemsToDelete)")
                for itemName in oldNewsItemsToDelete {
                    let itemURL = documentsDirectory.appendingPathComponent(itemName)
                    try? fileManager.removeItem(at: itemURL)
                    print("🗑️ 已成功删除: \(itemName)")
                }
            } else {
                print("本地资源无需清理。")
            }

            var downloadTasks: [(fileInfo: FileInfo, isIncremental: Bool)] = []

            let jsonFilesFromServer = serverVersion.files.filter { $0.type == "json" }
            let imageDirsFromServer = serverVersion.files.filter { $0.type == "images" }

            for jsonInfo in jsonFilesFromServer {
                let localFileURL = documentsDirectory.appendingPathComponent(jsonInfo.name)
                let correspondingImageDirName = "news_images_" + jsonInfo.name.components(separatedBy: "_").last!.replacingOccurrences(of: ".json", with: "")

                if fileManager.fileExists(atPath: localFileURL.path) {
                    guard let serverMD5 = jsonInfo.md5, let localMD5 = calculateMD5(for: localFileURL) else {
                        print("警告: 无法获取 \(jsonInfo.name) 的 MD5，跳过检查。")
                        continue
                    }
                    if serverMD5 != localMD5 {
                        print("MD5不匹配: \(jsonInfo.name)。计划更新。")
                        downloadTasks.append((fileInfo: jsonInfo, isIncremental: false))
                        let imageDirURL = documentsDirectory.appendingPathComponent(correspondingImageDirName)
                        try? fileManager.createDirectory(at: imageDirURL, withIntermediateDirectories: true)
                    } else {
                        print("MD5匹配: \(jsonInfo.name) 已是最新。")
                    }
                } else {
                    print("新文件: \(jsonInfo.name)。计划下载。")
                    downloadTasks.append((fileInfo: jsonInfo, isIncremental: false))
                    let imageDirURL = documentsDirectory.appendingPathComponent(correspondingImageDirName)
                    try? fileManager.createDirectory(at: imageDirURL, withIntermediateDirectories: true)
                }
            }

            for dirInfo in imageDirsFromServer {
                let localDirURL = documentsDirectory.appendingPathComponent(dirInfo.name)
                try? fileManager.createDirectory(at: localDirURL, withIntermediateDirectories: true)
            }

            if downloadTasks.isEmpty {
                if isManual {
                    await MainActor.run {
                        // 使用 Localized.upToDate 设置提示文字
                        self.syncMessage = Localized.upToDate // "已是最新版本"
                        // 2. 触发 UI 弹窗标记
                        self.showAlreadyUpToDateAlert = true
                        // 稍微延迟一点关闭 syncing 状态，或者立即关闭让弹窗独立显示
                        self.isSyncing = false 
                    }
                    // 1.5秒后自动重置状态（让弹窗消失）
                    resetStateAfterDelay(seconds: 1)
                }
                return
            }

            print("需要处理的任务列表: \(downloadTasks.map { $0.fileInfo.name })")

            self.isDownloading = true
            let totalTasks = downloadTasks.count

            for (index, task) in downloadTasks.enumerated() {
                self.progressText = "\(index + 1)/\(totalTasks)"
                self.downloadProgress = Double(index + 1) / Double(totalTasks)

                if task.fileInfo.type == "json" {
                    self.syncMessage = Localized.downloadingFiles
                    try await downloadSingleFile(named: task.fileInfo.name)
                }
            }

            self.isDownloading = false
            self.syncMessage = Localized.updateComplete
            self.progressText = ""

            // 👇 【新增】文件全部下载并覆盖完毕后，发送通知让 UI 刷新
            NotificationCenter.default.post(name: .newsDataDidUpdate, object: nil)

            resetStateAfterDelay()

        } catch {
            self.isDownloading = false
            self.isSyncing = false // 出错时立即停止
            throw error
        }
    }

    // 【辅助方法】确保 resetStateAfterDelay 能正确重置 alert 状态
    private func resetStateAfterDelay(seconds: TimeInterval = 2) {
        Task {
            try? await Task.sleep(for: .seconds(seconds))
            await MainActor.run {
                self.isSyncing = false
                self.syncMessage = ""
                self.progressText = ""
                // 【新增】自动关闭“已是最新”的弹窗
                withAnimation {
                    self.showAlreadyUpToDateAlert = false
                }
            }
        }
    }

    private func calculateMD5(for fileURL: URL) -> String? {
        var hasher = Insecure.MD5()
        do {
            let handle = try FileHandle(forReadingFrom: fileURL)
            defer { handle.closeFile() }
            while true {
                let data = handle.readData(ofLength: 1024 * 1024)
                if data.isEmpty { break }
                hasher.update(data: data)
            }
            let digest = hasher.finalize()
            return digest.map { String(format: "%02hhx", $0) }.joined()
        } catch {
            print("错误：计算文件 \(fileURL.lastPathComponent) 的 MD5 失败: \(error)")
            return nil
        }
    }

    // 【新增】版本号比对逻辑
    // 返回 true 表示 currentVersion < minVersion (需要强制更新)
    private func isVersion(_ current: String, lessThan min: String) -> Bool {
        let currentParts = current.split(separator: ".").compactMap { Int($0) }
        let minParts = min.split(separator: ".").compactMap { Int($0) }

        let count = max(currentParts.count, minParts.count)

        for i in 0..<count {
            let v1 = i < currentParts.count ? currentParts[i] : 0
            let v2 = i < minParts.count ? minParts[i] : 0

            if v1 < v2 { return true }
            if v1 > v2 { return false }
        }
        return false // 版本相同
    }

    private func getServerVersion() async throws -> ServerVersion {
        guard let url = URL(string: "\(serverBaseURL)/check_version") else { 
            throw URLError(.badURL) 
        }
        let (data, _) = try await urlSession.data(from: url)
        let version = try JSONDecoder().decode(ServerVersion.self, from: data)

        await MainActor.run {
            self.serverDate = version.server_date ?? ""
            self.sourceMappings = version.source_mappings ?? [:]
            self.serverLockedDays = version.locked_days ?? 0
            self.updateNotificationStatus(serverMessage: version.notification)

            // 持久化存储，防止离线时丢失基准
            if let sDate = version.server_date {
                UserDefaults.standard.set(sDate, forKey: "LastKnownServerDate")
            }

            if let time = version.update_time { self.serverUpdateTime = time }

            // 【新增】强制更新检查核心逻辑
            if let minVersion = version.min_app_version,
               let storeUrl = version.store_url {

                // 获取当前 App 版本号 (Info.plist)
                let currentVersion = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "1.0.0"

                if isVersion(currentVersion, lessThan: minVersion) {
                    print("当前版本 \(currentVersion) 低于最低要求 \(minVersion)，触发强制更新。")
                    self.showForceUpdate = true
                    self.appStoreURL = storeUrl
                } else {
                    self.showForceUpdate = false
                }
            }
        }

        return version
    }

    private func getLocalFiles() throws -> Set<String> {
        let contents = try fileManager.contentsOfDirectory(atPath: documentsDirectory.path)
        return Set(contents)
    }

    private func downloadSingleFile(named filename: String) async throws {
        guard var components = URLComponents(string: "\(serverBaseURL)/download") else { throw URLError(.badURL) }
        components.queryItems = [URLQueryItem(name: "filename", value: filename)]
        guard let url = components.url else { throw URLError(.badURL) }

        let (tempURL, response) = try await urlSession.download(from: url)

        guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }

        let destinationURL = documentsDirectory.appendingPathComponent(filename)
        if fileManager.fileExists(atPath: destinationURL.path) {
            try fileManager.removeItem(at: destinationURL)
        }
        try fileManager.moveItem(at: tempURL, to: destinationURL)
    }
}

import SwiftUI
import AuthenticationServices
import Security
import StoreKit // 引入 StoreKit

// 定义 Keychain 操作的错误类型
enum KeychainError: Error {
    case duplicateItem
    case unknown(OSStatus)
    case dataConversionError
    case itemNotFound
}

@MainActor
class AuthManager: NSObject, ObservableObject, ASAuthorizationControllerDelegate, ASAuthorizationControllerPresentationContextProviding {

    @Published var isLoggedIn: Bool = false
    @Published var isLoggingIn: Bool = false
    // 【新增】订阅状态
    @Published var isSubscribed: Bool = false
    @Published var subscriptionExpiryDate: String?

    @Published var errorMessage: String?
    @Published var showSubscriptionSheet: Bool = false // 控制是否显示订阅页

    // 存储从 Apple 获取的用户唯一标识符
    private(set) var userIdentifier: String?

    private let userIdentifierKey = "zhangyan.ONews"

    // 【重要】这里必须替换为你 App Store Connect 里设置的 Product ID
    private let subscriptionProductID = "com.zhangyan.onews.subscription.monthly"

    // 服务器地址
    private let serverBaseURL = "http://106.15.183.158:5001/api/ONews"

    // 【新增】缓存 Key
    private let cacheIsSubscribedKey = "AuthCache_IsSubscribed"
    private let cacheExpiryDateKey = "AuthCache_ExpiryDate"

    // 【新增】用于监听交易更新的任务
    private var updateListenerTask: Task<Void, Error>?

    override init() {
        super.init()
        // 应用启动时检查钥匙串中是否已有登录凭证
        checkUserInKeychain()

        // 【新增】启动交易监听器（处理应用外购买或自动续费）
        updateListenerTask = listenForTransactions()
    }

    deinit {
        updateListenerTask?.cancel()
    }

    // 检查钥匙串中的用户状态
    private func checkUserInKeychain() {
        do {
            if let userId = try loadUserIdentifierFromKeychain() {
                self.userIdentifier = userId
                self.isLoggedIn = true
                print("AuthManager: 本地已登录，User ID: \(userId)")

                // 【核心修复 1】启动时，先加载本地缓存的订阅状态
                // 这样即使网络请求失败，用户也能看到之前的订阅状态
                loadSubscriptionCache()

                // 【核心修复 2】
                // 启动时，不仅要检查服务器，更要直接检查 Apple 本地的 Entitlements (权限)。
                Task {
                    // 1. 优先检查 Apple 本地凭证 (这是最快且最准确的源头)
                    await updateSubscriptionStatus()

                    // 2. 同时/随后检查服务器状态 (用于同步安卓/跨平台状态或特殊后门)
                    await checkServerSubscriptionStatus()
                }
            } else {
                self.isLoggedIn = false
                self.isSubscribed = false
                clearSubscriptionCache() // 未登录时清理缓存
            }
        } catch {
            self.isLoggedIn = false
            self.isSubscribed = false
            print("AuthManager: 检查钥匙串时出错: \(error.localizedDescription)")
        }
    }

    // 触发 Apple 登录流程
    func signInWithApple() {
        guard !isLoggingIn else { return }
        isLoggingIn = true
        errorMessage = nil

        let request = ASAuthorizationAppleIDProvider().createRequest()
        request.requestedScopes = [.fullName, .email] // 请求获取用户全名和邮箱

        let controller = ASAuthorizationController(authorizationRequests: [request])
        controller.delegate = self
        controller.presentationContextProvider = self
        controller.performRequests()
    }

    // 登出
    func signOut() {
        do {
            try deleteUserIdentifierFromKeychain()
            self.userIdentifier = nil
            self.isLoggedIn = false
            self.isSubscribed = false // 登出后取消订阅状态
            self.subscriptionExpiryDate = nil
            clearSubscriptionCache() // 清理缓存
            print("AuthManager: 用户已成功登出。")
        } catch {
            // 即使删除失败，也在 UI 上表现为登出
            self.userIdentifier = nil
            self.isLoggedIn = false
            self.isSubscribed = false
            clearSubscriptionCache()
            print("AuthManager: 登出错误: \(error.localizedDescription)")
        }
    }

    // 【新增】删除账号功能
    func deleteAccount() async throws {
        guard let userId = userIdentifier else { throw URLError(.userAuthenticationRequired) }

        let url = URL(string: "\(serverBaseURL)/user/delete")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = ["user_id": userId]
        request.httpBody = try JSONEncoder().encode(body)

        let (_, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }

        // 服务器删除成功后，在本地执行退出登录并清理数据
        await MainActor.run {
            self.signOut()
            print("AuthManager: 账号已彻底删除并登出。")
        }
    }

    // 【新增】兑换邀请码
    func redeemInviteCode(_ code: String) async throws {
        guard let userId = userIdentifier else { throw URLError(.userAuthenticationRequired) }

        let url = URL(string: "\(serverBaseURL)/user/redeem")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = ["user_id": userId, "invite_code": code]
        request.httpBody = try JSONEncoder().encode(body)

        let (data, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse else {
            throw URLError(.badServerResponse)
        }

        if httpResponse.statusCode != 200 {
            // 尝试解析错误信息
            if let errorJson = try? JSONDecoder().decode([String: String].self, from: data),
               let serverMsg = errorJson["error"] {
                throw NSError(domain: "AuthError", code: httpResponse.statusCode, userInfo: [NSLocalizedDescriptionKey: serverMsg])
            }
            throw URLError(.badServerResponse)
        }

        // 解析成功响应
        struct RedeemResponse: Codable {
            let is_subscribed: Bool
            let subscription_expires_at: String?
        }

        let redeemResponse = try JSONDecoder().decode(RedeemResponse.self, from: data)

        await MainActor.run {
            self.isSubscribed = redeemResponse.is_subscribed
            self.subscriptionExpiryDate = redeemResponse.subscription_expires_at
            // 兑换成功也更新缓存
            self.saveSubscriptionCache(isSubscribed: redeemResponse.is_subscribed, expiryDate: redeemResponse.subscription_expires_at)
            print("AuthManager: 邀请码兑换成功，VIP 状态已激活。")
        }
    }

    // MARK: - StoreKit 2 Payment Logic (核心修改)

    // 【新增】监听交易流
    func listenForTransactions() -> Task<Void, Error> {
        return Task.detached {
            for await result in StoreKit.Transaction.updates {
                await self.handleTransactionUpdate(result)
            }
        }
    }

    // 辅助方法处理交易更新
    // 【修复】参数类型明确指定 StoreKit.Transaction
    private func handleTransactionUpdate(_ result: VerificationResult<StoreKit.Transaction>) async {
        do {
            let transaction = try checkVerified(result)
            await updateSubscriptionStatus()
            await transaction.finish()
        } catch {
            print("验证失败: \(error)")
        }
    }

    // 【修改】购买订阅 - 返回 Bool 表示是否购买成功
    // 返回 true: 购买成功
    // 返回 false: 用户取消或挂起
    func purchaseSubscription() async throws -> Bool {
        // 1. 检查登录
        guard let userId = userIdentifier else {
            throw URLError(.userAuthenticationRequired)
        }

        // 2. 获取商品信息
        let products = try await Product.products(for: [subscriptionProductID])
        guard let product = products.first else {
            throw NSError(domain: "StoreError", code: 404, userInfo: [NSLocalizedDescriptionKey: Localized.errProductNotFound]) // 使用双语
        }

        // 3. 发起购买
        let result = try await product.purchase()

        switch result {
        case .success(let verification):
            // 验证交易
            let transaction = try checkVerified(verification)

            // 购买成功，更新本地状态
            await updateSubscriptionStatus()

            // 同步给服务器
            try await syncPurchaseToServer(userId: userId)

            // 完成交易
            await transaction.finish()

            await MainActor.run {
                // 如果是 MainContentView 通过这个变量控制的弹窗，这里关闭它
                self.showSubscriptionSheet = false
            }

            return true // ✅ 返回成功

        case .userCancelled:
            print(Localized.errUserCancelled) // 使用双语
            return false // ❌ 返回失败（取消）

        case .pending:
            print("交易挂起")
            return false // ❌ 返回失败（挂起）

        @unknown default:
            print("未知状态")
            return false
        }
    }

    func handleAppDidBecomeActive() {
        Task {
            // 每次回到前台都刷一下，确保续订后第一时间同步给服务器
            await updateSubscriptionStatus()
            await checkServerSubscriptionStatus()
        }
    }

    // 【新增】恢复购买功能 (从 Finance 移植)
    func restorePurchases() async throws {
        // 1. 强制同步 App Store 交易信息 (StoreKit 2)
        // 这会弹出 Apple ID 密码输入框（如果是沙盒环境或长时间未操作）
        try await AppStore.sync()

        // 2. 重新检查所有权限
        await updateSubscriptionStatus()

        // 3. 如果需要，可以在这里再次同步到 Python 服务器 (可选)
        if let userId = userIdentifier, isSubscribed {
            try await syncPurchaseToServer(userId: userId)
        }
    }

    // MARK: - ASAuthorizationControllerDelegate

    // 授权成功回调
    func authorizationController(controller: ASAuthorizationController, didCompleteWithAuthorization authorization: ASAuthorization) {
        if let appleIDCredential = authorization.credential as? ASAuthorizationAppleIDCredential {
            guard let identityTokenData = appleIDCredential.identityToken,
                  let identityToken = String(data: identityTokenData, encoding: .utf8) else {
                handleSignInError(Localized.errNoIdentityToken) // 使用双语
                return
            }

            let userId = appleIDCredential.user

            // 发送 Token 和 UserID 到服务器进行验证和注册
            Task {
                do {
                    // 验证并获取订阅状态
                    try await sendTokenToServer(token: identityToken, userId: userId)
                    // 服务器验证成功后，在本地保存用户凭证
                    try saveUserIdentifierToKeychain(userId)

                    // 登录成功后，也立即检查一下本地 Apple 权限，双重保险
                    await updateSubscriptionStatus()

                    // 更新 UI 状态
                    await MainActor.run {
                        self.userIdentifier = userId
                        self.isLoggedIn = true
                        self.isLoggingIn = false

                        print("AuthManager: 登录成功。订阅状态: \(self.isSubscribed)")
                    }
                } catch {
                    handleSignInError("\(Localized.errServerVerifyFailed): \(error.localizedDescription)") // 使用双语
                }
            }
        } else {
            handleSignInError(Localized.errAppleIDCredentialFailed) // 使用双语
        }
    }

    // 授权失败回调
    func authorizationController(controller: ASAuthorizationController, didCompleteWithError error: Error) {
        // 用户取消登录操作不算作错误
        if (error as? ASAuthorizationError)?.code == .canceled {
            print("AuthManager: 用户取消了 Apple 登录。")
            handleSignInError(nil) // nil 表示是用户主动取消，不显示错误信息
        } else {
            print("AuthManager: Apple 登录授权失败: \(error.localizedDescription)")
            handleSignInError(Localized.errLoginFailedRetry) // 使用双语
        }
    }

    private func handleSignInError(_ message: String?) {
        DispatchQueue.main.async {
            self.isLoggingIn = false
            self.errorMessage = message
        }
    }

    // MARK: - ASAuthorizationControllerPresentationContextProviding

    // 告诉控制器在哪个窗口上显示登录界面
    func presentationAnchor(for controller: ASAuthorizationController) -> ASPresentationAnchor {
        return UIApplication.shared.connectedScenes
            .filter { $0.activationState == .foregroundActive }
            .compactMap { $0 as? UIWindowScene }
            .first?
            .windows
            .first { $0.isKeyWindow } ?? ASPresentationAnchor()
    }

    // MARK: - Server Communication

    private func sendTokenToServer(token: String, userId: String) async throws {
        let url = URL(string: "\(serverBaseURL)/auth/apple")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = ["identity_token": token, "user_id": userId]
        request.httpBody = try JSONEncoder().encode(body)

        let (data, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse, (200...299).contains(httpResponse.statusCode) else {
            throw URLError(.badServerResponse)
        }

        // 【修改】解析服务器返回的订阅状态
        struct AuthResponse: Codable {
            let is_subscribed: Bool
            let subscription_expires_at: String?
        }

        let authResponse = try JSONDecoder().decode(AuthResponse.self, from: data)

        await MainActor.run {
            self.isSubscribed = authResponse.is_subscribed
            self.subscriptionExpiryDate = authResponse.subscription_expires_at
            // 登录成功，保存缓存
            self.saveSubscriptionCache(isSubscribed: authResponse.is_subscribed, expiryDate: authResponse.subscription_expires_at)
        }
    }

    // 【新增】检查当前订阅状态（从 Apple 获取）
    func updateSubscriptionStatus() async {
        var hasActiveSubscription = false
        var latestExpirationDate: Date? = nil

        // 【修复】明确指定 StoreKit.Transaction
        for await result in StoreKit.Transaction.currentEntitlements {
            do {
                let transaction = try checkVerified(result)

                // 检查是否是我们的订阅产品
                if transaction.productID == subscriptionProductID {
                    // 检查过期时间
                    if let expirationDate = transaction.expirationDate {
                        if expirationDate > Date() {
                            hasActiveSubscription = true
                            latestExpirationDate = expirationDate
                            print("AuthManager: 发现有效订阅，过期时间: \(expirationDate)")
                        }
                    }
                }
            } catch {
                print("Failed to verify transaction: \(error)")
            }
        }

        // 更新 UI 状态
        let finalStatus = hasActiveSubscription
        let finalDateStr = latestExpirationDate?.ISO8601Format()

        await MainActor.run {
            if finalStatus {
                // 如果 Apple 说有效，直接覆盖所有状态，这是最高优先级
                self.isSubscribed = true
                self.subscriptionExpiryDate = finalDateStr
                // 本地 StoreKit 检查最权威，更新缓存
                self.saveSubscriptionCache(isSubscribed: true, expiryDate: finalDateStr)

                // ====================================================
                // 【核心修复】自动续费检测到后，必须同步给服务器！
                // ====================================================
                if let userId = self.userIdentifier {
                    Task {
                        print("AuthManager: 检测到有效订阅，正在同步至服务器...")
                        try? await self.syncPurchaseToServer(userId: userId)
                    }
                }
            }
            print("AuthManager: 本地 StoreKit 检查完成。结果: \(self.isSubscribed)")
        }
    }

    // 辅助函数：验证 JWS 签名
    // 【修复】删除了 static 关键字，使其成为实例方法，解决 "cannot be used on instance" 错误
    func checkVerified<T>(_ result: VerificationResult<T>) throws -> T {
        switch result {
        case .unverified:
            throw NSError(domain: "StoreError", code: 401, userInfo: [NSLocalizedDescriptionKey: Localized.errTransactionUnverified]) // 使用双语
        case .verified(let safe):
            return safe
        }
    }

    // MARK: - Server Sync (保留与 Python 的通信)

    // 复用你之前的逻辑，但在 StoreKit 成功后调用
    private func syncPurchaseToServer(userId: String) async throws {
        let url = URL(string: "\(serverBaseURL)/payment/subscribe")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        // 【核心修改】构建请求体
        var body: [String: Any] = ["user_id": userId]

        // 检查 AuthManager 中是否已经有了从 Apple 获取的过期时间
        // 注意：purchaseSubscription 和 restorePurchases 都会先调用 updateSubscriptionStatus
        // 所以此时 self.subscriptionExpiryDate 应该是最新的真实时间
        if let realExpiryDate = self.subscriptionExpiryDate {
            // 传给服务器字段：explicit_expiry
            body["explicit_expiry"] = realExpiryDate
        } else {
            // 如果实在拿不到时间（极少情况），再回退到加30天
            body["days"] = 30
        }

        request.httpBody = try JSONSerialization.data(withJSONObject: body)

        let (_, response) = try await URLSession.shared.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
            print("同步服务器失败，但本地已购买成功")
            return
        }
        print("服务器同步成功")
    }

    // 【新增】检查服务器上的订阅状态
    func checkServerSubscriptionStatus() async {
        guard let userId = userIdentifier else { return }
        guard let url = URL(string: "\(serverBaseURL)/user/status?user_id=\(userId)") else { return }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            struct StatusResponse: Codable {
                let is_subscribed: Bool
                let subscription_expires_at: String?
            }
            let status = try JSONDecoder().decode(StatusResponse.self, from: data)

            await MainActor.run {
                // 1. 如果服务器说 "是 VIP"
                if status.is_subscribed {
                    self.isSubscribed = true
                    self.subscriptionExpiryDate = status.subscription_expires_at
                    // 服务器校验成功，更新缓存
                    self.saveSubscriptionCache(isSubscribed: true, expiryDate: status.subscription_expires_at)
                    print("AuthManager: 服务器确认 VIP 身份。")
                } 
                // 2. 如果服务器说 "不是 VIP"
                else {
                    // 【核心修复】
                    // 只有在 "本地 Apple 凭证也过期" 的情况下，才听服务器的。
                    // 如果我们刚刚通过 StoreKit 确认了本地权限有效，就忽略服务器的 "false"。
                    if self.isSubscribedViaAppleLocal() {
                        print("AuthManager: 服务器返回未订阅，但本地 Apple 凭证有效。忽略服务器结果，保持 VIP。")
                        // 可选：这里可以触发一次静默的同步，告诉服务器更新状态
                        Task { try? await self.syncPurchaseToServer(userId: userId) }
                    } else {
                        // 确实没订阅，也没本地凭证，那才是真的没订阅
                        self.isSubscribed = false
                        self.subscriptionExpiryDate = nil
                        self.clearSubscriptionCache()
                        print("AuthManager: 服务器确认未订阅，且无本地凭证。")
                    }
                }
            }
        } catch {
            print("AuthManager: 检查服务器状态失败: \(error)")
            // 网络失败时不操作，保持现有状态（依赖缓存或本地凭证）
        }
    }

    // 【新增】辅助函数：判断当前是否是基于 Apple 本地凭证的订阅
    // 我们需要一个简单的判断：如果当前 isSubscribed 为 true，且 expiryDate 是将来，
    // 我们就假设它是有效的（因为 updateSubscriptionStatus 会定期运行保证它准确）
    private func isSubscribedViaAppleLocal() -> Bool {
        guard self.isSubscribed else { return false }
        guard let dateStr = self.subscriptionExpiryDate else { return false } // 永久会员可能没日期，视情况而定

        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]

        // 尝试解析
        if let date = formatter.date(from: dateStr) {
            return date > Date()
        }

        // 兼容简单格式
        let simpleFormatter = ISO8601DateFormatter()
        simpleFormatter.formatOptions = [.withFullDate, .withDashSeparatorInDate]
        if let date = simpleFormatter.date(from: dateStr) {
             // 简单日期通常指当天的 00:00，为了保险起见，如果是今天或未来，都算有效
             return date >= Calendar.current.startOfDay(for: Date())
        }

        // 如果是 "2099" 这种永久标记，也算有效
        if dateStr.starts(with: "2099") { return true }

        return false
    }

    // MARK: - 缓存逻辑 (解决网络启动慢/失败的问题)

    private func saveSubscriptionCache(isSubscribed: Bool, expiryDate: String?) {
        UserDefaults.standard.set(isSubscribed, forKey: cacheIsSubscribedKey)
        if let date = expiryDate {
            UserDefaults.standard.set(date, forKey: cacheExpiryDateKey)
        } else {
            UserDefaults.standard.removeObject(forKey: cacheExpiryDateKey)
        }
    }

    private func loadSubscriptionCache() {
        let cachedStatus = UserDefaults.standard.bool(forKey: cacheIsSubscribedKey)
        let cachedExpiry = UserDefaults.standard.string(forKey: cacheExpiryDateKey)

        if cachedStatus {
            // 只有当缓存是 true 时，我们才需要验证日期
            // 如果缓存里有日期，检查是否已过期
            if let dateStr = cachedExpiry {
                // 简单解析 ISO8601
                let formatter = ISO8601DateFormatter()
                formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]

                // 尝试解析，如果解析失败尝试简单格式
                var date = formatter.date(from: dateStr)
                if date == nil {
                    let simpleFormatter = ISO8601DateFormatter()
                    simpleFormatter.formatOptions = [.withFullDate, .withDashSeparatorInDate]
                    date = simpleFormatter.date(from: dateStr)
                }

                if let validDate = date {
                    if validDate > Date() {
                        // 缓存有效且未过期
                        self.isSubscribed = true
                        self.subscriptionExpiryDate = dateStr
                        print("AuthManager: 已加载本地缓存，暂时赋予 VIP 权限。")
                        return
                    } else {
                        print("AuthManager: 本地缓存已过期。")
                    }
                } else {
                    // 如果是永久 VIP (2099年) 或者日期解析不了但状态是 true，也暂时信任
                    // 假设 2099 这种简单字符串
                    if dateStr.starts(with: "2099") {
                        self.isSubscribed = true
                        self.subscriptionExpiryDate = dateStr
                        return
                    }
                }
            }
        }

        // 如果缓存无效或未订阅
        // self.isSubscribed = false // 默认就是 false，不用重复赋值
    }

    private func clearSubscriptionCache() {
        UserDefaults.standard.removeObject(forKey: cacheIsSubscribedKey)
        UserDefaults.standard.removeObject(forKey: cacheExpiryDateKey)
    }


    // ... (Keychain Helpers 保持不变) ...
    private func saveUserIdentifierToKeychain(_ identifier: String) throws {
        guard let data = identifier.data(using: .utf8) else { throw KeychainError.dataConversionError }
        try? deleteUserIdentifierFromKeychain()

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: userIdentifierKey,
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleWhenUnlockedThisDeviceOnly
        ]

        let status = SecItemAdd(query as CFDictionary, nil)
        guard status == errSecSuccess else {
            if status == errSecDuplicateItem {
                throw KeychainError.duplicateItem
            }
            throw KeychainError.unknown(status)
        }
        print("AuthManager: 用户 ID 已保存到钥匙串。")
    }

    private func loadUserIdentifierFromKeychain() throws -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: userIdentifierKey,
            kSecReturnData as String: kCFBooleanTrue!,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var dataTypeRef: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &dataTypeRef)

        if status == errSecSuccess {
            guard let data = dataTypeRef as? Data,
                  let identifier = String(data: data, encoding: .utf8) else {
                return nil
            }
            return identifier
        } else if status == errSecItemNotFound {
            return nil // 找不到是正常情况
        } else {
            throw KeychainError.unknown(status)
        }
    }

    private func deleteUserIdentifierFromKeychain() throws {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: userIdentifierKey
        ]

        let status = SecItemDelete(query as CFDictionary)
        if status != errSecSuccess && status != errSecItemNotFound {
            throw KeychainError.unknown(status)
        }
    }
}

