// MARK: - 详情页选项行
struct DetailOptionRow: View {
    let option: PredictionOption
    let rank: Int
    let color: Color

    private var barWidth: CGFloat {
        guard let val = Fmt.percentValue(option.value) else { return 0.05 }
        return max(0.03, val / 100.0)
    }

    var body: some View {
        VStack(spacing: 8) {
            HStack(spacing: 12) {
                // 排名
                Text("#\(rank)")
                    .font(.system(size: 13, weight: .bold, design: .monospaced))
                    .foregroundColor(color)
                    .frame(width: 32, alignment: .leading)

                // 标签
                Text(option.displayLabel)
                    .font(.system(size: 15, weight: .medium))
                    .foregroundColor(.white)
                    .lineLimit(2)

                Spacer()

                // 变化值
                if let change = option.change, !change.isEmpty {
                    Text(change)
                        .font(.system(size: 12, weight: .medium, design: .monospaced))
                        .foregroundColor(changeColor(change))
                        .fixedSize()
                }

                // 百分比
                Text(option.value)
                    .font(.system(size: 16, weight: .bold, design: .rounded))
                    .foregroundColor(.white)
                    .padding(.horizontal, 14)
                    .padding(.vertical, 8)
                    .background(
                        RoundedRectangle(cornerRadius: 20)
                            .fill(color.opacity(0.15))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 20)
                            .stroke(color.opacity(0.4), lineWidth: 1)
                    )
                    .fixedSize()
            }

            // 进度条
            GeometryReader { geo in
                ZStack(alignment: .leading) {
                    RoundedRectangle(cornerRadius: 3)
                        .fill(color.opacity(0.15))
                        .frame(height: 4)
                    RoundedRectangle(cornerRadius: 3)
                        .fill(color)
                        .frame(width: geo.size.width * barWidth, height: 4)
                }
            }
            .frame(height: 4)
        }
        .padding(14)
        .background(Color.cardBg)
        .cornerRadius(12)
    }

    private func changeColor(_ change: String) -> Color {
        if change.contains("▲") { return .green }
        if change.contains("▼") { return .red }
        return .secondary
    }
}

import SwiftUI

struct PredictionSearchView: View {
    let items: [PredictionItem]
    let isSubscribed: Bool
    let onLockedTap: () -> Void

    @Environment(\.dismiss) var dismiss
    @State private var searchText = ""
    @FocusState private var isSearchFocused: Bool

    private var results: [PredictionItem] {
        let keyword = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !keyword.isEmpty else { return [] }

        return items.filter { item in
            if item.name.lowercased().contains(keyword) { return true }
            for opt in item.options {
                if opt.label.lowercased().contains(keyword) { return true }
            }
            return false
        }
    }

    var body: some View {
        NavigationStack {
            ZStack {
                Color.appBg.ignoresSafeArea()

                VStack(spacing: 0) {
                    // 搜索栏
                    HStack(spacing: 12) {
                        HStack {
                            Image(systemName: "magnifyingglass")
                                .foregroundColor(.secondary)
                            TextField("搜索预测话题或选项...", text: $searchText)
                                .foregroundColor(.white)
                                .focused($isSearchFocused)
                                .autocorrectionDisabled()

                            if !searchText.isEmpty {
                                Button { searchText = "" } label: {
                                    Image(systemName: "xmark.circle.fill")
                                        .foregroundColor(.secondary)
                                }
                            }
                        }
                        .padding(10)
                        .background(Color.cardBg)
                        .cornerRadius(12)

                        Button("取消") { dismiss() }
                            .foregroundColor(.blue)
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 12)

                    // 结果
                    if searchText.isEmpty {
                        VStack(spacing: 16) {
                            Spacer()
                            Image(systemName: "magnifyingglass")
                                .font(.system(size: 40))
                                .foregroundColor(.secondary.opacity(0.3))
                            Text("输入关键词搜索")
                                .foregroundColor(.secondary)
                            Spacer()
                        }
                    } else if results.isEmpty {
                        VStack(spacing: 16) {
                            Spacer()
                            Image(systemName: "doc.text.magnifyingglass")
                                .font(.system(size: 40))
                                .foregroundColor(.secondary.opacity(0.3))
                            Text("未找到匹配结果")
                                .foregroundColor(.secondary)
                            Spacer()
                        }
                    } else {
                        ScrollView {
                            LazyVStack(spacing: 12) {
                                Text("\(results.count) 个结果")
                                    .font(.caption).foregroundColor(.secondary)
                                    .frame(maxWidth: .infinity, alignment: .leading)
                                    .padding(.horizontal, 16)

                                ForEach(results) { item in
                                    PredictionCardView(
                                        item: item,
                                        isSubscribed: isSubscribed,
                                        onLockedTap: onLockedTap
                                    )
                                    .padding(.horizontal, 16)
                                }

                                Spacer().frame(height: 40)
                            }
                            .padding(.top, 8)
                        }
                    }
                }
            }
            .onAppear { isSearchFocused = true }
        }
    }
}

import Foundation
import SwiftUI
import Combine

@MainActor
class PreferenceManager: ObservableObject {

    @Published var selectedSubtypes: Set<String> = []

    private let storageKey = "Pred_SelectedSubtypes"

    init() {
        if let saved = UserDefaults.standard.array(forKey: storageKey) as? [String] {
            selectedSubtypes = Set(saved)
        }
    }

    func save() {
        UserDefaults.standard.set(Array(selectedSubtypes), forKey: storageKey)
    }

    func toggle(_ subtype: String) {
        if selectedSubtypes.contains(subtype) {
            selectedSubtypes.remove(subtype)
        } else {
            selectedSubtypes.insert(subtype)
        }
    }

    func selectAll(subtypes: [String]) {
        selectedSubtypes = Set(subtypes)
    }

    var hasPreferences: Bool { !selectedSubtypes.isEmpty }

    // 从数据中提取 type → [subtype] 映射
    static func extractCategories(from items: [PredictionItem]) -> [(type: String, subtypes: [String])] {
        var typeMap: [String: Set<String>] = [:]

        for item in items {
            let t = item.type
            let s = item.subtype
            typeMap[t, default: Set()].insert(s)
        }

        return typeMap
            .sorted { $0.key < $1.key }
            .map { (type: $0.key, subtypes: $0.value.sorted()) }
    }
}

import SwiftUI

struct PreferenceSelectionView: View {
    @EnvironmentObject var syncManager: SyncManager
    @EnvironmentObject var prefManager: PreferenceManager
    @Environment(\.dismiss) var dismiss

    let isOnboarding: Bool
    var onComplete: (() -> Void)? = nil

    @State private var expandedTypes: Set<String> = []

    private var categories: [(type: String, subtypes: [String])] {
        let all = syncManager.polymarketItems + syncManager.kalshiItems
        return PreferenceManager.extractCategories(from: all)
    }

    private var allSubtypes: [String] {
        categories.flatMap { $0.subtypes }
    }

    var body: some View {
        ZStack {
            Color.appBg.ignoresSafeArea()

            VStack(spacing: 0) {
                // 顶部标题
                VStack(spacing: 8) {
                    Text(isOnboarding ? "选择您感兴趣的话题" : "偏好设置")
                        .font(.title2.bold())
                        .foregroundColor(.white)
                    Text("选择您想追踪的预测类别")
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
                .padding(.top, 20)
                .padding(.bottom, 16)

                // 全选/全不选
                HStack {
                    Button("全选") {
                        withAnimation { prefManager.selectAll(subtypes: allSubtypes) }
                    }
                    .font(.caption.bold())
                    .foregroundColor(.blue)

                    Text("·").foregroundColor(.secondary)

                    Button("全不选") {
                        withAnimation { prefManager.selectedSubtypes.removeAll() }
                    }
                    .font(.caption.bold())
                    .foregroundColor(.blue)

                    Spacer()

                    Text("已选 \(prefManager.selectedSubtypes.count) 项")
                        .font(.caption)
                        .foregroundColor(.secondary)
                }
                .padding(.horizontal, 20)
                .padding(.bottom, 12)

                // 类别列表
                ScrollView {
                    LazyVStack(spacing: 12) {
                        ForEach(categories, id: \.type) { category in
                            CategoryCard(
                                typeName: category.type,
                                subtypes: category.subtypes,
                                isExpanded: expandedTypes.contains(category.type),
                                selectedSubtypes: $prefManager.selectedSubtypes,
                                onToggleExpand: {
                                    withAnimation(.spring(response: 0.3)) {
                                        if expandedTypes.contains(category.type) {
                                            expandedTypes.remove(category.type)
                                        } else {
                                            expandedTypes.insert(category.type)
                                        }
                                    }
                                }
                            )
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 100)
                }

                Spacer()
            }

            // 底部确认按钮
            VStack {
                Spacer()
                Button {
                    prefManager.save()
                    if isOnboarding {
                        onComplete?()
                    } else {
                        dismiss()
                    }
                } label: {
                    Text(isOnboarding ? "开始探索" : "保存设置")
                        .font(.headline)
                        .foregroundColor(.white)
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 16)
                        .background {
                            if prefManager.selectedSubtypes.isEmpty {
                                Color.gray
                            } else {
                                LinearGradient(colors: [.blue, .purple], startPoint: .leading, endPoint: .trailing)
                            }
                        }
                        .cornerRadius(16)
                }
                .disabled(prefManager.selectedSubtypes.isEmpty)
                .padding(.horizontal, 20)
                .padding(.bottom, 30)
                .background(
                    LinearGradient(colors: [Color.appBg.opacity(0), Color.appBg],
                                   startPoint: .top, endPoint: .bottom)
                    .frame(height: 100)
                    .allowsHitTesting(false)
                )
            }
        }
        .navigationBarBackButtonHidden(isOnboarding)
        .onAppear {
            // 首次进入自动展开所有类别
            expandedTypes = Set(categories.map { $0.type })
        }
    }
}

// MARK: - 类别卡片
struct CategoryCard: View {
    let typeName: String
    let subtypes: [String]
    let isExpanded: Bool
    @Binding var selectedSubtypes: Set<String>
    let onToggleExpand: () -> Void

    private var selectedCount: Int {
        subtypes.filter { selectedSubtypes.contains($0) }.count
    }

    var body: some View {
        VStack(spacing: 0) {
            // 大类标题（不可选）
            Button(action: onToggleExpand) {
                HStack {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(typeName)
                            .font(.headline)
                            .foregroundColor(.white)
                        Text("\(selectedCount)/\(subtypes.count) 已选")
                            .font(.caption)
                            .foregroundColor(.secondary)
                    }

                    Spacer()

                    Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                        .font(.caption.bold())
                        .foregroundColor(.secondary)
                }
                .padding(16)
            }

            // 子类标签（可选）
            if isExpanded {
                let columns = [GridItem(.adaptive(minimum: 100, maximum: 200), spacing: 10)]

                LazyVGrid(columns: columns, spacing: 10) {
                    ForEach(subtypes, id: \.self) { subtype in
                        let isSelected = selectedSubtypes.contains(subtype)

                        Button {
                            withAnimation(.spring(response: 0.25)) {
                                if isSelected {
                                    selectedSubtypes.remove(subtype)
                                } else {
                                    selectedSubtypes.insert(subtype)
                                }
                            }
                        } label: {
                            HStack(spacing: 6) {
                                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                                    .font(.system(size: 14))
                                    .foregroundColor(isSelected ? .blue : .secondary)

                                Text(subtype)
                                    .font(.system(size: 13, weight: .medium))
                                    .foregroundColor(isSelected ? .white : .secondary)
                                    .lineLimit(1)
                            }
                            .padding(.horizontal, 14)
                            .padding(.vertical, 10)
                            .background(
                                RoundedRectangle(cornerRadius: 10)
                                    .fill(isSelected ? Color.blue.opacity(0.2) : Color.white.opacity(0.05))
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: 10)
                                    .stroke(isSelected ? Color.blue.opacity(0.5) : Color.clear, lineWidth: 1)
                            )
                        }
                    }
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 16)
            }
        }
        .background(Color.cardBg)
        .cornerRadius(16)
    }
}

